public class DataAccessLayer
{
    private readonly string secureConnectionString;
    private readonly string encryptionKey;
    private readonly SqlConnection secureConnection;
    private Action<IDataReader> callbackHandler;

    public DataAccessLayer(string secureConnectionString, 
                           string encryptionKey, 
                           SqlConnection secureConnection)
    {
        this.secureConnectionString = secureConnectionString;
        this.encryptionKey = encryptionKey;
        this.secureConnection = secureConnection;
    }

    public void ExecuteSecureParameterizedQuery(string query, 
                                                List<object> parameters, 
                                                Action<IDataReader> callbackHandler)
    {
        if (string.IsNullOrEmpty(this.secureConnectionString))
            throw new ArgumentException("Invalid connection string");

        // Check encryption key and connection object here...

        this.callbackHandler = callbackHandler ?? 
                               throw new ArgumentNullException("Callback handler can't be null");

        var policy = Policy
            .Handle<SqlException>()
            .WaitAndRetry(5, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        // Execute the database operation
        policy.Execute(() =>
        {
            using (var command = new SqlCommand(query, this.secureConnection))
            {
                for (int i = 0; i < parameters.Count; i++)
                {
                    command.Parameters.AddWithValue("@p" + i, parameters[i]);
                }

                // Assume we have a helper method GetDataReader() which executes the query...
                using (var reader = this.GetDataReader(command)) 
                {
                    try
                    {
                        this.callbackHandler(reader);
                    }
                    catch (Exception e)
                    {
                        Log.Error("Failed to process result: " + e.Message);
                    }   
                }
            }
        });

        // Remember to manage the secure connection string, encryption key etc...
    }

    private IDataReader GetDataReader(SqlCommand command) 
    {
        this.secureConnection.Open();
        return command.ExecuteReader();
    }
}
