**2. Define Employee Schema (models/Employee.ts)**

```typescript
import { model, Document, Model, Schema } from 'mongoose';
export interface IEmployee extends Document {
    name: string;
    jobTitle: string;
    department: string;
    location: string;
}
const EmployeeSchema = new Schema({
    name: String,
    jobTitle: String,
    department: String,
    location: String
});
export const Employee: Model<IEmployee> = model('Employee', EmployeeSchema);
```
**3. Create a Service to fetch employees from HR APIs (services/employees.ts)**

```typescript
import { IEmployee, Employee } from '../models/Employee';
import fetch from 'node-fetch';
class EmployeeService{
    async getAllEmployees(): Promise<IEmployee[]> {
        // Fetch data from HR APIs and store in MongoDB
        const res = await fetch('http://hr_api.com/employees');
        const employees = await res.json();
        return Employee.insertMany(employees);
    }
}
export default new EmployeeService();
```
**4. Create a controller for your routes (controllers/employeesController.ts)**

```typescript
import { Request, Response } from 'express';
import employeeService from '../services/employeeService';
class EmployeeController{
    async getAll(req: Request, res: Response){
        const employees = await employeeService.getAllEmployees();
        return res.json({success: true, data: employees});
    }
}
export default new EmployeeController();
```
**5. Setup your routes (routes/employeesRoutes.ts)**

```typescript
import { Router } from 'express';
import employeeController from '../controllers/employeeController';
const router = Router();
router.get('/', employeeController.getAll);
export default router;
```
**6. Connect your routes to your app (app.ts)**

```typescript
import express, { Express } from 'express';
import mongoose from 'mongoose';
import employeesRoutes from './routes/employeesRoutes';
const app: Express = express();
// Connect to MongoDB
mongoose.connect('mongodb://localhost/organization', { useNewUrlParser: true, useUnifiedTopology: true });
app.use('/api/v1/employees', employeesRoutes);
app.listen(3000, () => console.log("App is listening on port 3000"));
```
