['This task requires a more than one file implementation solution and is complex to be implemented in this text-based format due to its complexity. Here are some basic concepts which should help you get started with building such an application. 

The first part of your code will require the `fs` module for recursively reading files, and `path` module for handling paths.
```javascript
const fs = require('fs');
const path = require('path');

let searchFilesInDir = (startPath, filter) => {
    let results = [];
    if (!fs.existsSync(startPath)){
        console.log("no dir ", startPath);
        return;
    }

    var files=fs.readdirSync(startPath);
    for(var i=0;i<files.length;i++){
        var filename=path.join(startPath,files[i]);
        var stat = fs.lstatSync(filename);
        if (stat.isDirectory()){
            results = results.concat(searchFilesInDir(filename,filter)); //recurse
        } else if (filename.indexOf(filter) > -1) {
            console.log('-- found: ', filename);
            results.push(filename);
        }
    };

    return results;
}
```
