['Here is an example of how the code might look like using `hyper` for HTTP client, `tokio` for async runtime and `envy` for environment variable management:

```rust
use std::collections::HashMap;
use hyper::{Body, Client, Request};
use tokio::time::timeout;
use std::sync::Arc;
use envy::prelude::*;
use url::Url;
use anyhow::Result;

#[derive(Clone, Debug, Deserialize)]
struct Config {
    url: Url,
    timeout_secs: u64,
    auth: Option<Auth>,
}

#[derive(Clone, Debug, Deserialize)]
enum Auth {
    Basic { username: String, password: String },
    OauthBearerToken { token: String },
}

impl Config {
    fn from_env() -> Result<Self> {
        let config: Self = envy::from_env()?;
        Ok(config)
    }
}

struct HttpClient {
    client: Client,
    config: Arc<Config>,
}

impl HttpClient {
    fn new() -> Result<Self> {
        let config = Config::from_env()?;
        Ok(Self {
            client: Client::new(),
            config: Arc::new(config),
        })
    }

    async fn get(&self, path: &str) -> Result<Body> {
        let url = self.config.url.join(path)?;
        let mut request_builder = Request::get(url);

        if let Some(auth) = &self.config.auth {
            match auth {
                Auth::Basic { username, password } => {
                    request_builder = request_builder.basic_auth(username, Some(password));
                },
                Auth::OauthBearerToken { token } => {
                    request_builder = request_builder.bearer_auth(token);
                },
            };
        }

        let mut request = request_builder.body(Body::empty()).unwrap();
        let client = &self.client;

        timeout(std::time::Duration::from_secs(self.config.timeout_secs), || async {
            let response = client.request(request).await?;

            match response.status() {
                hyper::Status::Ok => Ok(response.into_body()),
                _ => Err(anyhow::anyhow![format_args![
                    "Failed to get {}: {}", url, response.status()
                ]]),
            }
        })
        .await?;

        Ok(response)
    }
}
```
