        abilities_[ability] = Cooldown(cooldown_time);
    }

    bool activateAbility(const std::string& ability) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (abilities_.find(ability) != abilities_.end() && abilities_[ability].isReady()) {
