```c
#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <errno.h>

int main() {
    DIR *dir;
    struct dirent *ent;
    FILE *fp;
    char command[512];

    if ((dir = opendir(".")) != NULL) {
        /* print all the files and directories within directory */
        while ((ent = readdir(dir)) != NULL) {
            if (strstr(ent->d_name, ".jpg") != NULL || strstr(ent->d_name, ".jpeg") != NULL || strstr(ent->d_name, ".png") != NULL || strstr(ent->d_name, ".gif") != NULL) {
                sprintf(command, "convert %s image.pdf", ent->d_name);
                system(command);
            }
        }
        closedir(dir);
    } else {
        /* could not open directory */
        perror("");
        return -1;
    }

    sprintf(command, "convert image.pdf output.pdf");
    system(command);

    // remove all the temporary pdf files
    sprintf(command, "rm image-*.pdf");
    system(command);

    return 0;
}
```

This program requires ImageMagick installed and accessible through your command line. Also, this code does not handle concurrent processing or efficient resource usage for large datasets, as these would be complex to implement without a full understanding of the project requirements. It's also worth noting that using `system()` function can pose security risks, so please consider alternatives if possible.

