            Console.WriteLine($"Decrypted Message: {decryptedMessage}, Max Number from CSV: {maxNumberFromCSV}");
        }
    }

    public int FindMaxFromInput(string csvFilePath)
    {
        try
        {
            var lines = File.ReadAllLines(csvFilePath);

            return lines.Select(int.Parse).Max();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to find max number from CSV: {ex}");
            throw;
        }
    }
}

