['Here is an example of how you could structure such a component using C#:

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Caching.Memory;

public class HashService : IHashService
{
    private readonly ILogger<HashService> _logger;
    private readonly IMemoryCache _cache;
    private readonly IExternalLoggingApi _externalLoggingApi;

    public HashService(ILogger<HashService> logger, IMemoryCache cache, IExternalLoggingApi externalLoggingApi)
    {
        _logger = logger;
        _cache = cache;
        _externalLoggingApi = externalLoggingApi;
    }

    public async Task<string> GetMd5HashAsync(string input)
    {
        // Check if the result is cached
        string cachedResult = _cache.Get<string>(input);
        if (!string.IsNullOrEmpty(cachedResult))
            return cachedResult;

        try
        {
            using (var md5Hash = MD5.Create())
            {
                byte[] data = md5Hash.ComputeHash(Encoding.UTF8.GetBytes(input));

                // Create a new StringBuilder to collect the bytes and create a string
                var sBuilder = new StringBuilder();

                // Loop through each byte of the hashed data 
                for (int i = 0; i < data.Length; i++)
                    sBuilder.Append(data[i].ToString("x2"));

                string result = sBuilder.ToString();

                _cache.Set(input, result);

                // Log the hash computation event
                await _externalLoggingApi.LogHashComputationEventAsync(result);

                return result;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while generating MD5 hash");
            throw new HashGenerationFailedException("An error occurred during the hashing process", ex);
        }
    }
}
```
This code uses the `IMemoryCache` provided by .NET Core to cache the result of computation. The choice of eviction policy and its configuration will depend on specific requirements such as memory usage, data freshness etc., but for example a sliding expiration with a small duration could be an option. 

As per best practices, exception handling is crucial in ensuring stability and reliability in a production environment. If an error occurs during hash computation or API interaction, it's caught by the catch block which logs the error and throws a custom exception (`HashGenerationFailedException`) for downstream systems to handle. 

However, this code does not include details about how you would implement logging via an external API as that would likely involve specific requirements of your system. You might want to use some library or framework provided by the API provider or create a simple client class yourself, depending on their API documentation and restrictions. 

Remember to replace `IExternalLoggingApi` with actual interface that you will implement for communicating with external logging API. This code assumes that an implementation of this interface provides a method (e.g., LogHashComputationEventAsync) to log the hash computation event.
