    try {
        // Call external service to generate password and cache result
        const response = await axios.post(encryptionServiceUrl, {}, { auth: { username: 'user', password: 'pass' } });
        myCache.set('password', response.data);

        return response.data;
    } catch (error) {
        logger.logError(`Failed to get encrypted password from external service - ${JSON.stringify(error)}`);
        throw error;
    }
}

