        var data = response.data;

        // Refresh fields
        for (var i = 0; i < fieldNames.length; i++) {
          var fieldName = fieldNames[i];
          $window[fieldName] = data[fieldName];
        }

        // Analyze and count books from the Old Testament in refreshed content
        service.countBooksFromOldTestament(data);
      })
      .catch(function errorCallback(response) {
        console.log('Failed to refresh fields', response);
      });
    };

    // Function to analyze and count books from the Old Testament in refreshed content
    service.countBooksFromOldTestament = function(content) {
      var regex = /\bbook\b/g;

      // Remove punctuation and special characters, match only whole words
      var strippedContent = content.replace(/[^a-zA-Z0-9 ]/g, "").split(" ");

      var bookCount = 0;
      for (var i = 0; i < strippedContent.length; i++) {
        if (regex.test(strippedContent[i])) {
          bookCount++;
        }
      }

      console.log('Number of books from the Old Testament:', bookCount);
    };

    return service;
  });
```
