#include <iostream>
#include <string>
#include <chrono>
#include <mutex>
#include <map>

class ConfigEntry {
public:
    std::string id;
    std::string configParams;
    std::string changeLog;
    std::map<std::string, std::string> metadata;
    std::chrono::system_clock::time_point lastUpdateTimestamp;
};

class ConfigManager {
private:
    std::mutex mtx; // used for concurrency control
    std::map<std::string, ConfigEntry> configEntries;  // using a map to store configurations
public:
    void addConfig(const ConfigEntry& entry) {
        std::lock_guard<std::mutex> lock(mtx);   // for thread safety
        if (configEntries.find(entry.id) != configEntries.end()) {
            std::cout << "Configuration with ID " + entry.id + " already exists." << std::endl;
            return;
        }
        configEntries[entry.id] = entry;
    }

    ConfigEntry getConfig(const std::string& id) {
        std::lock_guard<std::mutex> lock(mtx);   // for thread safety
        if (configEntries.find(id) == configEntries.end()) {
            throw std::runtime_error("Configuration with ID " + id + " not found.");
        }
        return configEntries[id];
    }

    void updateConfig(const ConfigEntry& entry) {
        std::lock_guard<std::mutex> lock(mtx);   // for thread safety
        if (configEntries.find(entry.id) == configEntries.end()) {
            throw std::runtime_error("Configuration with ID " + entry.id + " not found.");
        }
        configEntries[entry.id] = entry;
    }
};
```
This code represents a basic configuration manager that supports adding, getting and updating configurations concurrently in a thread-safe manner. 

