    while (1) {
        // Generate log data here. This is just a placeholder.
        Log* log = malloc(sizeof(Log));
        log->type = 0;
        log->content = malloc(256);

        pthread_t thread;
        if (pthread_create(&thread, NULL, process_log, log) != 0) {
            perror("Failed to create a new thread");
            free(log->content);
            free(log);
        }
    }

    return NULL;
}

int main() {
    pthread_t generate_and_process_logs_thread;
    if (pthread_create(&generate_and_process_logs_thread, NULL, generate_and_process_logs, NULL) != 0) {
        perror("Failed to create a new thread");
        return 1;
    }

    pthread_join(generate_and_process_logs_thread, NULL);
    return 0;
}
