import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api")
public class SensorDataService {
    private final DataIngestion dataIngestion;
    private final DataStorage dataStorage;
    private final RealTimeAnalytics realTimeAnalytics;
    private final AlertingMechanism alertingMechanism;
    private final ServiceResilience serviceResilience;

    public SensorDataService(DataIngestion dataIngestion, DataStorage dataStorage, 
                             RealTimeAnalytics realTimeAnalytics, AlertingMechanism alertingMechanism, 
                             ServiceResilience serviceResilience) {
        this.dataIngestion = dataIngestion;
        this.dataStorage = dataStorage;
        this.realTimeAnalytics = realTimeAnalytics;
        this.alertingMechanism = alertingMechanism;
        this.serviceResilience = serviceResilience;
    }

    @PostMapping("/processData")
    public void processData(@RequestBody SensorData data) {
        // Process the incoming sensor data.
        dataIngestion.handle(data);
        dataStorage.save(data);
        realTimeAnalytics.analyze(data);
        alertingMechanism.triggerAlerts(data);
    }

