#include <sys/ipc.h> 
#include <sys/shm.h> 
#include <stdio.h> 

// Size of the shared memory segment 
#define SH_SIZE 1024 
char SHM_KEY = 'A'; 

int main() { 
    key_t key; 
    int shmid; 
    char *shm, *s; 

    // Generate the unique key. 
    key = ftok(SHM_KEY,0); 

    // Create the segment. 
    if ((shmid = shmget(key, SH_SIZE, IPC_CREAT | 0666)) < 0) { 
        perror("shmget"); 
        return 1; 
    } 

    // Now we attach the segment to our data space. 
    if ((shm = shmat(shmid, NULL, 0)) == (char *) -1) { 
        perror("shmat"); 
        return 1; 
    } 

    // We can now read what is in the shared memory segment. 
    for (s = shm; *s != '\0'; s++) 
        putchar(*s); 

    putchar('\n'); 

    // Detach from the segment 
    if(shmdt(shm) == -1){
        perror("shmdt");
        return 1;
    }

    return 0; 
}
```
