            $isValid = $this->validatePasswordStrength($newPassword);

            if (!$isValid) {
                throw new Exception('Invalid password');
            }

            foreach ($this->authServices as $service) {
                $isValid = $service->validate($userId, $newPassword);

                if (!$isValid) {
