typedef struct {
    int bufferSize;
    /* other configuration fields */
} LogConfig;

void trimAndLogString(char* inputStr, int strLen, int maxLogSize, FILE* logFd, LogConfig* logConfig, pthread_mutex_t* threadPool) {
    if (inputStr == NULL || logFd == NULL || logConfig == NULL || threadPool == NULL) return;

    /* Acquire lock to prevent race conditions */
    pthread_mutex_lock(threadPool);

    int length = strnlen(inputStr, maxLogSize);
    if (length < strLen) {
        fprintf(logFd, "Warning: Input string was truncated\n");
    }

    /* Truncate the input string to fit into the buffer */
    char trimmedStr[maxLogSize];
    memcpy(trimmedStr, inputStr, maxLogSize);

    fprintf(logFd, "%s", trimmedStr);

    /* Release lock after operation */
    pthread_mutex_unlock(threadPool);
}
```
In this example, we have a `trimAndLogString` function that truncates the input string and logs it to the specified file descriptor. We also use mutexes for synchronization to prevent data corruption or loss due to concurrent access from multiple threads. 

