int validateAccessToken(char* jsonString) {
    json_error_t error;
    json_t *root = json_loads(jsonString, 0, &error);

    if(!root) {
        fprintf(stderr, "error: on line %d: %s\n", error.line, error.text);
        return -1; // or handle error as you wish
    }

    if(!json_is_object(root)) {
        json_decref(root);
        fprintf(stderr, "error: root is not an object\n");
        return -1; // or handle error as you wish
    }

    json_t *accessToken = json_object_get(root, "access_token");

    if(!json_is_string(accessToken)) {
        json_decref(root);
        fprintf(stderr, "error: access_token is not a string\n");
        return -1; // or handle error as you wish
    }

    const char *accessTokenString = json_string_value(accessToken);

    if (strlen(accessTokenString) != ACCESS_TOKEN_LENGTH) { // replace ACCESS_TOKEN_LENGTH with the required length of access token. 
        json_decref(root);
        fprintf(stderr, "error: access_token is not correct length\n");
        return -1; // or handle error as you wish
    }

    /* add more validation checks here */

    json_decref(root);
    return 0;
}
```
