using Microsoft.Extensions.Logging;
using Microsoft.AspNetCore.Mvc;

public interface IHashService {
    Task<string> GetMD5Async(string input);
    Task<string> GetSHA256Async(string input);
}

public class HashService : IHashService {
    private readonly ILogger<HashService> _logger;

    public HashService(ILogger<HashService> logger) {
        _logger = logger;
    }

    public async Task<string> GetMD5Async(string input) {
        return await ComputeHashAsync(input, MD5.Create());
    }

    public async Task<string> GetSHA256Async(string input) {
        return await ComputeHashAsync(input, SHA256.Create());
    }

    private async Task<string> ComputeHashAsync(string input, HashAlgorithm algorithm) {
        try {
            var bytes = Encoding.UTF8.GetBytes(input);
            var hashBytes = await algorithm.ComputeHashAsync(bytes);

            return Convert.ToBase64String(hashBytes);
        } catch (Exception ex) {
            _logger.LogError(ex, "Failed to compute hash");
            throw;
        }
    }
}
```

