use std::sync::{Arc, Mutex};
use std::thread;

pub struct ProcessAndLogNetworkStream {
    buffer: Arc<Mutex<Vec<String>>>,
}

impl ProcessAndLogNetworkStream {
    pub fn new() -> Self {
        Self {
            buffer: Arc::new(Mutex::new(vec![String::new(); BUFFER_SIZE])),
        }
    }

    pub fn process(&self, log_entry: String) {
        let mut buffer = self.buffer.lock().unwrap();

        // Assuming a simple round-robin style buffer where old data is discarded if over capacity
        let index = self.index % BUFFER_SIZE; 
        buffer[index] = log_entry;
        self.index += 1;
    }

