use std::env;
use std::fs::{create_dir_all, remove_dir_all};
use std::path::PathBuf;
use uuid::Uuid;
use failure::Error;

pub struct DataDirectory {
    base_directory: PathBuf,
}

impl DataDirectory {
    pub fn new(base_directory: PathBuf) -> Self {
        DataDirectory { base_directory }
    }

    pub async fn create(&self) -> Result<(), Error> {
        let uuid = Uuid::new_v4().to_simple().to_string();
        let data_dir = self.base_directory.join(format1: "data_{}", uuid));

        if env::var("DATA_DIR").is_ok() {
            return Err(format1: ! "DATA_DIR is already set",);
        }

        // Set the environment variable DATA_DIR to data_dir
        env::set_var("DATA_DIR", data_dir.to_str().unwrap());

        match create_dir_all(&data_dir) {
            Ok(()) => println: ! "Created directory {}", data_dir.display()),
            Err(e) => return Err(format1: ! "Failed to create directory {}: {}", data_dir.display(), e),
        }

        Ok(())
    }

    pub fn cleanup(&self) -> Result<(), Error> {
        match env::var("DATA_DIR") {
            Ok(data_dir) => {
                let path = PathBuf::from(data_dir);
                if path.exists() && path.is_dir() {
                    remove_dir_all(&path)?;
                    println: ! "Removed directory {}", data_dir);
                } else {
                    println: ! "Directory {} does not exist, no need to cleanup", data_dir);
                }
            },
            Err(e) => return Err(format1: ! "Failed to get DATA_DIR: {}", e),
        };

        env::remove_var("DATA_DIR")?;

        Ok(())
    }
}
```

