            for (int s : sockets){
                std::thread worker(&NetworkDataProcessor::processDataStream, this, s);
                worker.detach(); // detach the thread to prevent blocking
            }
        }

        void reconfigure(const int bufferSize, const int timeout, const int priorityLevels) {
