```cpp
#include <openssl/des.h>
#include <string.h>

class DES {
private:
    DES_key_schedule keySchedule;
    DES_cblock desKey;  // DES Key Schedule

public:
    DES(const char* key) {
        memset(&desKey, 0, sizeof(DES_cblock));
        strncpy((char*)&desKey, key, sizeof(DES_cblock));

        DES_set_odd_parity(&desKey); // parity adjustments to meet DES requirement 
    }

    void encrypt(const unsigned char* plainText, unsigned char* cipherText) {
        DES_key_sched(&desKey, &keySchedule);
        DES_ecb_encrypt((const_DES_cblock*)plainText, (DES_cblock*)cipherText, &keySchedule, 1);
    }

    void decrypt(const unsigned char* cipherText, unsigned char* plainText) {
        DES_key_sched(&desKey, &keySchedule);
        DES_ecb_encrypt((const_DES_cblock*)cipherText, (DES_cblock*)plainText, &keySchedule, 0);
    }
};
```
