```cpp
#include <list>
#include <algorithm>
#include <mutex>
#include <string>
#include <stdexcept>
#include "externalAPI.h"  // replace this with actual external API header

class StringListManager {
private:
    std::list<std::string> list;
    ExternalApi api;  // Assuming there is a class defined in the provided header
    std::mutex mtx;  // Mutex for managing concurrency
public:
    void insertAfter(const std::string& target, const std::string& insertion, char delimiter) {
        std::lock_guard<std::mutex> lock(mtx);  // Lock mutex

        auto it = find(list.begin(), list.end(), target);
        if (it == list.end()) {
            list.push_back(insertion);
        } else {
            ++it;   // Move iterator to next position
            while(it != list.end() && *it == target) ++it;  // Skip duplicates
            list.insert(it, insertion);
            mergeDuplicates(target, delimiter);
        }
    }

    void mergeDuplicates(const std::string& target, char delimiter) {
        auto it = find(list.begin(), list.end(), target);

        while (it != list.end()) {
            auto next_it = it;
            ++next_it;
            // If the next element is also same as target, then merge
            if (next_it != list.end() && *next_it == target) {
                *it += delimiter + *next_it;  // Merge strings using delimiter
                list.erase(next_it);  // Erase the merged string
            } else {
                ++it;  // Move iterator to next position
            }
        }
    }

    void saveToApi() {
        std::lock_guard<std::mutex> lock(mtx);  // Lock mutex

        try {
            api.saveList(list);  // Assuming there is a function in external API to save list
        } catch (const std::exception& e) {
            throw std::runtime_error("Error saving data: " + std::string(e.what()));
        }
    }

    void loadFromApi() {
        std::lock_guard<std::mutex> lock(mtx);  // Lock mutex

        try {
            list = api.loadList();  // Assuming there is a function in external API to load list
        } catch (const std::exception& e) {
            throw std::runtime_error("Error loading data: " + std::string(e.what()));
        }
    }
};
```
