        // Store the hashed and salted token in the database with expiry time
        $hashedToken = password_hash($token, PASSWORD_DEFAULT);
        $expiryTime = time() + 3600;  // One hour from now

        $sql = "INSERT INTO tokens (email, token, expires) VALUES (?, ?, ?)";
        $stmt= $this->dbh->prepare($sql);
        $stmt->execute([$email, $hashedToken, $expiryTime]);

