        ];

        // Dynamic template creation based on the serviceProvider

        return $message;
    }

    private function handleError($e) {
        error_log('Error: ' . $e->getMessage());

        if ($e instanceof \React\Http\Message\ResponseException && $e->getCode() === 503) {
            // Handle email service provider outage
            $this->fallbackToLocalStorage($message);
        } elseif ($e instanceof PDOException) {
            // Handle database connection issues
            $this->retryDatabaseOperation();
        } else {
            throw $e;
        }
    }

    private function retryDatabaseOperation() {
        $attempts = 0;

        while ($attempts < 3) {
            $attempts++;

            try {
                $this->dbh = new PDO('mysql:host=localhost;dbname=test', 'user', 'pass');
                return true;
            } catch (\Exception $e) {
                error_log('Database connection issue. Retry attempt: ' . $attempts);
                sleep(5);  // Sleep for 5 seconds before retrying
            }
        }

        throw new Exception("Failed to reconnect to the database after multiple attempts");
    }

    private function fallbackToLocalStorage($message) {
        // Store message locally and schedule a retry later
    }
}
