    if (!head) {
        custom_error_report("Memory allocation failed");
        return NULL;
    }

    StateList* current = head;
    int i;
    for (i = 0; i < numStates - 1; ++i) {
        current->state = states[i];
        current->next = (StateList*) malloc(sizeof(StateList));

        if (!current->next) {
