public:
    explicit http_connection(beast::tcp_stream stream) : stream_(std::move(stream)) {}

    void start() {
        read_request();
        check_deadline();
    }

private:
    beast::tcp_stream stream_;
    beast::flat_buffer buffer_{8192};
    http::request<http::dynamic_body> request_;

    void fail(beast::error_code ec, char const* what) {
        std::cerr << what << ": " << ec.message() << "\n";
    }

    void on_read(beast::error_code ec, std::size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if (ec == http::error::end_of_stream) return;

        if (ec) return fail(ec, "read");

        handle_request();
    }

    void on_write(beast::error_code ec, std::size_t bytes_transferred, bool close) {
        boost::ignore_unused(bytes_transferred);

        if (ec) return fail(ec, "write");

        if (close) { do_close(); } else { res = nullptr; read_request(); }
    }

    void do_close() {
        beast::error_code ec;
        stream_.socket().shutdown(tcp::socket::shutdown_send, ec);
    }
};
```
