// A thread-safe class to handle the data ingestion process.
class DataIngestion {
private:
    mutable std::mutex mtx; // Mutex for thread safety.
    std::vector<std::shared_ptr<DataSource>> sources; // Vector of shared pointers to DataSources.
public:
    void addDataSource(const std::shared_ptr<DataSource>& source) {
        std::lock_guard<std::mutex> lock(mtx); // Lock the mutex.
        sources.push_back(source); 
    }

    void startIngestion() {
        for (auto& source : sources) {
            std::thread t([this, &source](){
                mtx.lock();
                std::cout << "Processing data from: " << source->getData() << std::endl;
                mtx.unlock(); 
            });
            t.join(); // Wait for the thread to finish.
        }
    }
};

int main() {
    DataIngestion di;

    auto externalProvider = std::make_shared<ExternalProvider>();
    di.addDataSource(externalProvider);

    di.startIngestion(); // Start the data ingestion process.

    return 0;
}
