typedef struct {
    pthread_mutex_t mutex;
    json_object *bundle;
} Bundle;

void loadBundle(const char *filepath, Bundle **bundle) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    *bundle = malloc(sizeof(Bundle));
    if (!*bundle) {
        return;
    }

    pthread_mutex_init(&(*bundle)->mutex, &attr);

    // Implement archive decompression and JSON parsing here. 
    // For example, using json-c for JSON parsing:
    (*bundle)->bundle = json_object_from_file(filepath);
}

int countItemsInBundle(const Bundle *bundle) {
    pthread_mutex_lock(&bundle->mutex);

    int itemCount = 0;

    if (json_object_get_type(bundle->bundle) == json_type_array) {
        itemCount = json_object_array_length(bundle->bundle);
    }

    pthread_mutex_unlock(&bundle->mutex);

    return itemCount;
}
```

