typedef struct token_t {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token; // NULLable
} Token;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

CURLcode send_request(Token *token) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        char url[256];
        sprintf(url, "https://example.com/validate?access_token=%s", token->access_token);

        curl_easy_setopt(curl, CURLOPT_URL, url);

        /* Perform the request, res will get the return code */ 
        res = curl_easy_perform(curl);

        /* Check for errors */ 
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        /* always cleanup */ 
        curl_easy_cleanup(curl);
    }

    return res;
}

void *validate_token(void *arg) {
    Token *token = (Token *) arg;

    pthread_mutex_lock(&lock);
    CURLcode result = send_request(token);

    if (result != CURLE_OK) {
        // Handle error.
    }

    /* Process the response here... */ 

    free(token->access_token);
    free(token->token_type);
    free(token->refresh_token);
    pthread_mutex_unlock(&lock);
}

int main() {
