```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;
using Polly;
using Serilog;

public class DataIngestionService : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly IConfiguration _configuration;
    private BlockingCollection<byte[]> _buffer = new BlockingCollection<byte[]>();
    private Task _workerTask;
    private CancellationTokenSource _cts = new CancellationTokenSource();

    public DataIngestionService(IHttpClientFactory httpClientFactory, IConfiguration configuration)
    {
        _httpClient = httpClientFactory.CreateClient("dataUpload"); // assuming you have a named client in your HttpClientFactory
        _configuration = configuration;

        var policy = Policy
            .Handle<SqlException>()
            .Or<HttpRequestException>(e => e.StatusCode >= System.Net.HttpStatusCode.InternalServerError)
            .WaitAndRetryAsync(5, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
        _workerTask = Task.Run(() => Worker(_cts.Token), _cts.Token);
    }

    public void IngestData(byte[] data)
    {
        _buffer.Add(data);
    }

    private async Task Worker(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            var item = _buffer.Take(); // blocks until a buffer is available
            await ProcessDataAsync(item);
        }
    }

    private async Task ProcessDataAsync(byte[] data)
    {
        try
        {
            using (var content = new ByteArrayContent(data))
            using (var response = await _httpClient.PostAsync("your_database_endpoint", content))
            {
                response.EnsureSuccessStatusCode(); // throws exception if not successful
            }
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Failed to process data");
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _workerTask?.Wait(); // waits for the task to complete before disposing
        _buffer.Dispose();
        _httpClient.Dispose();
    }
}
```
This is just a basic skeleton and you should implement appropriate data validation, checksum verification, security policies and error handling as per your requirements. 

