    try {
        const decoded = jwt.verify(token, JWT_SECRET_KEY);
        req.user = decoded;
    } catch (err) {
        return res.status(401).send("Invalid Token");
    }
    return next();
});

app.get('/config/:tenantId', async (req, res) => {
    const tenantId = req.params.tenantId;
    let config = cache.get(tenantId);

    if(!config){
        // Fetch configuration from third-party service
        const response = await fetch('https://third-party-service/api/v1/config', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({tenantId})
        });

        config = await response.json();
        cache.set(tenantId, config); // Save in cache
    }

    res.json(config);
});

app.listen(3000, () => console.log('Server is running'));
