import boto3
from azure.storage.blob import BlobServiceClient
from google.cloud import storage

class CloudStorage:
    def __init__(self, provider):
        self.provider = provider

        if provider == 'aws':
            self.client = boto3.client('s3')
        elif provider == 'azure':
            self.client = BlobServiceClient.from_connection_string(<your-connection-string>)
        elif provider == 'gcp':
            self.client = storage.Client()

    def upload_file(self, file_name, bucket):
        if self.provider == 'aws':
            self.client.upload_file(file_name, bucket, file_name)
        elif self.provider == 'azure':
            blob_client = self.client.get_blob_client(container=bucket, blob=file_name)
            with open(file_name, "rb") as data:
                blob_client.upload_blob(data)
        elif self.provider == 'gcp':
            bucket = self.client.get_bucket(bucket)
            blob = bucket.blob(file_name)
            blob.upload_from_filename(file_name)

    def download_file(self, file_name, bucket):
        if self.provider == 'aws':
            self.client.download_file(bucket, file_name, file_name)
        elif self.provider == 'azure':
            blob_client = self.client.get_blob_client(container=bucket, blob=file_name)
            with open(file_name, "wb") as data:
                data.write(blob_client.download_blob().readall())
        elif self.provider == 'gcp':
            bucket = self.client.get_bucket(bucket)
            blob = bucket.blob(file_name)
            blob.download_to_filename(file_name)
``` 

