["The problem can't be solved directly here, as it requires a complex, multi-file solution with many specific details like logging mechanism, external services interactions, error handling mechanisms etc. It is also hard to provide full production ready code here as this platform does not support running actual code. 

But I can provide you an example of how you could start such task:

```cpp
#include <vector>
#include <random>
#include <mutex>
#include <thread>
#include <chrono>
#include <iostream>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

class PDUListManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus_;
    std::mutex mtx_;
    std::thread workerThread_;
    bool isRunning_ = false;
    int updatesFrequency_ = 500; // in ms

public:
    ~PDUListManager() {
        if (workerThread_.joinable()) {
            isRunning_ = false;
            workerThread_.join();
        }
    }

    void startUpdates(int updatesFrequency) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (!isRunning_) {
            isRunning_ = true;
            updatesFrequency_ = updatesFrequency;
            workerThread_ = std::thread(&PDUListManager::worker, this);
        }
    }

    void stopUpdates() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (isRunning_) {
            isRunning_ = false;
            workerThread_.join();
        }
    }

private:
    void worker() {
        while (isRunning_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(updatesFrequency_));

            // Generate a random NFAPI_CRC_INDICATION_PDU_T here...
            NFAPI_CRC_INDICATION_PDU_T pdu;
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 65535); // for example

            pdu.RX_UE_INFORMATION_TAG = dis(gen);
            pdu.RNTI = static_cast<unsigned>(dis(gen));

            std::lock_guard<std::mutex> lock(mtx_);
            // Update list here...
            pdus_.push_back(pdu);
        }
    }
