```cpp
#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <random>

// Define a structure for NFAPI_CRC_INDICATION_PDU_T
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

class PacketManager {
public:
    void ProcessNFAPackets() {
        std::thread producer([this](){ this->ProducePackets(); });
        std::thread consumer([this](){ this->ConsumePackets(); });

        producer.join();
        consumer.join();
    }

private:
    void ProducePackets() {
        while(true) {
            NFAPI_CRC_INDICATION_PDU_T packet = GeneratePacket();

            std::unique_lock<std::mutex> lock(mtx_);
            queue_.push(packet);
            lock.unlock();
            condVar_.notify_one();
        }
    }

    void ConsumePackets() {
        while(true) {
            std::unique_lock<std::mutex> lock(mtx_);
            condVar_.wait(lock, [this]{ return !queue_.empty(); });

            auto packet = queue_.front();
            queue_.pop();

            // Process the packet as needed...

            lock.unlock();
        }
    }

    NFAPI_CRC_INDICATION_PDU_T GeneratePacket() {
        // Generate a random packet here..

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);

        NFAPI_CRC_INDICATION_PDU_T packet = {dis(gen), dis(gen), dis(gen)};

        return packet;
    }

private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> queue_;
    std::mutex mtx_;
    std::condition_variable condVar_;
};
```
This is a basic approach to the problem. The performance can be optimized by using smart pointers for managing memory and leveraging thread pooling for better CPU utilization. Also, the producer-consumer model can be expanded for batch updates or other use cases which might require different types of concurrency control mechanisms. 

