public class MarketTickProcessorService : IMarketTickProcessorService
{
    private readonly IDistributedCache _cache;
    private readonly IMarketDataValidationService _validationService;

    public MarketTickProcessorService(IDistributedCache cache, 
        IMarketDataValidationService validationService)
    {
        _cache = cache;
        _validationService = validationService;
    }

    public async Task ProcessAsync(Stream data)
    {
        using (var reader = new StreamReader(data))
        {
            var jsonString = await reader.ReadToEndAsync();
            var marketTicks = JsonConvert.DeserializeObject<List<MarketTick>>(jsonString);

            foreach (var tick in marketTicks)
            {
                if (!await _validationService.ValidateAsync(tick.Symbol))
                    continue; // or throw exception, depending on your requirements

                var cachedAggregation = await _cache.GetAsync<AggregationResult>(tick.Symbol);
                if (cachedAggregation == null)
                {
                    var newAggregation = new AggregationResult
                    {
                        Symbol = tick.Symbol,
                        TotalVolume = tick.Volume
                    };
                    await _cache.SetAsync(tick.Symbol, newAggregation);
                }
                else
                {
                    cachedAggregation.TotalVolume += tick.Volume;
                    await _cache.SetAsync(tick.Symbol, cachedAggregation);
                }
            }
        }
    }
}
