bool isOauth2TokenValid(const std::string& jsonStr) {
    rapidjson::Document document;
    if (document.Parse(jsonStr.c_str()).HasParseError()) 
        return false; // If JSON string is not valid, return false immediately.

    if (!document.HasMember("access_token") || !document["access_token"].IsString() || 
        !document.HasMember("expires_in") || !document["expires_in"].IsUint() || 
        !document.HasMember("token_type") || !document["token_type"].IsString()) {
