import java.awt.*;
import java.awt.image.*;
import javax.imageio.*;
import java.io.*;
import java.util.concurrent.*;

public class DynamicImageProcessor {
    private static final int MAX_WIDTH = 800; // maximum width of the resized image
    private static final int MAX_HEIGHT = 600; // maximum height of the resized image

    public void process(File input, File output) throws Exception {
        BufferedImage originalImage = ImageIO.read(input);
        int type = getType(originalImage);

        double scaleX = (double) MAX_WIDTH / originalImage.getWidth();
        double scaleY = (double) MAX_HEIGHT / originalImage.getHeight();
        double scale = Math.min(scaleX, scaleY);

        BufferedImage scaledImage = new BufferedImage((int)(originalImage.getWidth() * scale), 
                                                    (int)(originalImage.getHeight() * scale), type);
        Graphics2D graphics2D = scaledImage.createGraphics();
        AffineTransform affineTransform = AffineTransform.getScaleInstance(scale, scale);
        graphics2D.drawRenderedImage(originalImage, affineTransform);

        ImageIO.write(scaledImage, "jpg", output); // change to the appropriate format based on input image type
    }

    private int getType(BufferedImage img) {
        return (img.getTransparency() == Transparency.OPAQUE) ? BufferedImage.TYPE_INT_RGB : BufferedImage.TYPE_INT_ARGB;
    }
}
```

