    }
}

void *processFile(void *arg) {
    int c = (long) arg;
    FILE *fpIn = stdin;

    if (c == 'f') {
        fpIn = gzopen(optarg, "r");
        if (!fpIn) {
            perror("Error while opening the input file.");
            exit(1);
        }
    }

    apiCall(c, fpIn);

    if (fpIn != stdin)
        gzclose(fpIn);

    return NULL;
}

int main(int argc, char **argv) {
    int opt_index = 0;
    pthread_t threads[argc];

    while (1) {
        int c = getopt_long(argc, argv, "f:cvo:", long_options, &opt_index);

        if (c == -1) break;

        switch (c) {
            case 'm': ; // Implement manpage display.
                printf("Usage: %s [-cfvo]\n", argv[0]);
                exit(0);
            default: ;
                pthread_create(&threads[optind], NULL, processFile, (void*)(long)c);
        }
    }

    for (int i = 1; i < argc; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error while joining threads.");
            exit(1);
        }
    }

    return 0;
}
```
