['Below is an outline of how this could be implemented in C, which requires more than a code block can show. This includes a lot of advanced design considerations and practices that are not easily realized through code snippets alone. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>

typedef struct {
    void *handle;
    int (*hash_func)(const char*);
} HashPlugin;

HashPlugin load_plugin(const char *path) {
    HashPlugin plugin = { NULL, NULL };

    // Open the library
    plugin.handle = dlopen(path, RTLD_NOW | RTLD_GLOBAL);

    if (plugin.handle == NULL) {
        fprintf(stderr, "Failed to load plugin: %s\n", dlerror());
        return plugin;
    }

    // Load the symbol - the hash function in this case
    plugin.hash_func = dlsym(plugin.handle, "hash_func");

    if (plugin.hash_func == NULL) {
        fprintf(stderr, "Failed to load 'hash_func' from plugin: %s\n", dlerror());
        return plugin;
    }

    return plugin;
}

void unload_plugin(HashPlugin *plugin) {
    if (dlclose(plugin->handle) != 0) {
        fprintf(stderr, "Failed to unload plugin: %s\n", dlerror());
    } else {
        plugin->handle = NULL;
        plugin->hash_func = NULL;
    }
}
```

The above code shows how to load a dynamic library (a.k.a., shared object or DSO) and extract a symbol, in this case the hash function. 

A production quality cryptographic library would be significantly more complex and require careful design and extensive testing. This is just an example showing how one might start building such a system using dynamically loaded plugins.

