    mutable std::shared_mutex mtx_;  
    std::thread syncThread_; 

public:
    SharedStringCache() {
        syncThread_ = std::thread([this](){ this->syncWithExternalAPI(); });
    }

    ~SharedStringCache() {
        // set the termination condition for the background thread.
        terminateSyncThread = true; 
        syncThread_.join();
    }

    void insert(const std::string& str, const std::string& delimiter) {
        std::lock_guard<std::shared_mutex> lock(mtx_); // writer lock

        if (data.find(str) != data.end()) 
            data[str]++; 
        else 
            data[str] = 1;
    }

    std::vector<std::string> getAll() const {
        std::shared_lock<std::shared_mutex> lock(mtx_); // reader lock

        std::vector<std::string> allStrings; 
        for (const auto& pair : data) 
            for(int i = 0; i < pair.second; ++i)
                allStrings.push_back(pair.first);
        return allStrings;
    }

    void syncWithExternalAPI() {
        while(!terminateSyncThread){
            // implement your synchronization logic here using cpr or any other HTTP library

