#include <random>
#include <chrono>
#include <mutex>
#include <iostream>

namespace RandomSystem {
    class MersenneTwisterGenerator {
        public:
            static std::mt19937& getInstance() {
                static std::mt19937 generator(static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count()));
                return generator;
            }

            static void seedGenerator(const unsigned int& seed) {
                std::lock_guard<std::mutex> lock(_mtx);
                _instance.seed(seed);
            }

            template <typename T>
            static T generateRandomNumber() {
                // Add your logging mechanism here, like 
                // std::cout << "Generating random number at time: " << currentTimeInMillis();

                if (std::is_integral<T>::value) {
                    return static_cast<T>(_instance());
                } else if (std::is_floating_point<T>::value) {
                    return static_cast<T>(_instance()) / static_cast<T>(std::mt19937::max());
                }
            }

        private:
            inline static std::mutex _mtx;  // Thread safety
    };
}
```
