void Octree::Insert(const glm::vec3& point) {
    // Check if the point fits within our bounds
    if (!ContainsPoint(point)) return;

    if (IsLeafNode()) {
        points_.push_back(point);

        if (points_.size() > MAX_POINTS && depth_ < MAX_DEPTH) {
            Split();
        }
    } else {
        for (auto& child : children_) {
            child->Insert(point);
        }
    }
}
