    // Custom Log Filter
    public interface Filter {
        boolean isLoggable(String message);
    }

    // Asynchronous Buffering
    private ExecutorService executor;

    public LoggingFramework() {
        this.executor = Executors.newFixedThreadPool(10);
    }

    public void log(Level level, String message) {
        executor.submit(() -> logger.log(level, message));
    }

    // Log Aggregation
    private ConcurrentHashMap<String, AtomicInteger> aggregatedLogs = new ConcurrentHashMap<>();

    public void aggregateAndLog(Level level, String message) {
        aggregatedLogs.computeIfAbsent(message, k -> new AtomicInteger()).incrementAndGet();

        if (aggregatedLogs.get(message).intValue() % 10 == 0) {
            log(level, "Aggregated: " + message);
        }
    }
}
