public class HashService : IHashService
{
    private readonly IDistributedCache _cache;
    private readonly ExternalAuthApiClient _authApiClient;
    private readonly Polly.Retry.AsyncRetryPolicy _retryPolicy;

    public HashService(IDistributedCache cache, 
                       ExternalAuthApiClient authApiClient)
    {
        _cache = cache;
        _authApiClient = authApiClient;

        // setup retry policy with exponential backoff and circuit breaker pattern
        _retryPolicy = Policy
            .Handle<ExternalServiceException>()
            .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)));
    }

    public async Task<string> ComputeAndStoreHashAsync(string input)
    {
        var cachedValue = await _cache.GetStringAsync(input);

        if (cachedValue != null) return cachedValue;

        // compute hash value with retries and fallback
        string result = await _retryPolicy.ExecuteAndCaptureAsync(async () => {
            var authResult = await _authApiClient.Authenticate();
            if (!authResult.Success) throw new ExternalServiceException();

            // compute hash value here...
        }).Result;

        // store in cache
        await _cache.SetStringAsync(input, result);

        return result;
    }
}
