pthread_mutex_t _configLock = PTHREAD_MUTEX_INITIALIZER;

void trimAndLogString(char *input, int size, logConfig *config) {
    // Null and invalid state checks
    if (input == NULL || size <= 0 || config == NULL) {
        printf("Invalid input\n");
        return;
    }

    pthread_mutex_lock(&_configLock);
    logConfig *currentConfig = getCurrentLogConfig(); // Function to fetch the current log config 
    pthread_mutex_unlock(&_configLock);

    if (strcmp(currentConfig, config) != 0) {
        printf("Warning: Config changed during operation. Aborting.\n");
        return;
    }

    // Truncate the string if its size exceeds maxLogSize and append a warning message 
    int logSize = min(size, MAX_LOG_SIZE);
    char* truncatedInput = malloc(logSize + 1);
    strncpy(truncatedInput, input, logSize);
    if (size > MAX_LOG_SIZE) {
        printf("Warning: String was too large. It has been truncated.\n");
    }

    // Use lock-free operations to add the string data into the buffer 
    pthread_spin_lock(&_bufferLock);
    memcpy(_buffer + _writePos, truncatedInput, logSize);
    atomic_fetch_add(&_writePos, logSize);
    pthread_spin_unlock(&_bufferLock);

    // Add the log entry into the queue for delayed processing 
    addToQueue(_logQueue, truncatedInput);
}
```
