#include <stdio.h>
#include <string.h>

int main(){
    int server_fd, new_socket; long valread;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Creating socket file descriptor 
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) { 
        perror("In socket"); 
        exit(EXIT_FAILURE); 
    }

    address.sin_family = AF_INET; 
    address.sin_addr.s_addr = INADDR_ANY; 
    address.sin_port = htons(8080); 

    // Forcefully attaching socket to the port 8080 
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) { 
        perror("In bind"); 
        exit(EXIT_FAILURE); 
    }
    if (listen(server_fd, 3) < 0){ 
        perror("In listen"); 
        exit(EXIT_FAILURE); 
    }

    while(1){
        printf("\n--------- Waiting for new connection ----------\n\n");
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen))<0){
            perror("In accept");
            exit(EXIT_FAILURE);
        }

        char buffer[30000] = {0}; 
        valread = read( new_socket , buffer, 30000); 
        printf("%s\n",buffer );
        write(new_socket , "HTTP/1.1 200 OK\nContent-Type: text/html\nContent-Length: 45\n\n<h1>Hello from C HTTP Server</h1>" , strlen("HTTP/1.1 200 OK\nContent-Type: text/html\nContent-Length: 45\n\n<h1>Hello from C HTTP Server</h1>"));
        printf("-------- Response sent -------\n");
        close(new_socket);
    }
   return 0;
}
