['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* createList() {
    LinkedList *list = (LinkedList*) malloc(sizeof(LinkedList));
    if (list == NULL) return NULL; // Handle allocation failure

    list->head = NULL;
    pthread_mutex_init(&(list->mutex), NULL);
    return list;
}

void addElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T *data) {
    if (data->RNTI > 65535) {
        // Handle invalid RNTI value
        return;
    }

    pthread_mutex_lock(&(list->mutex));
    data->next = list->head;
    if (list->head != NULL) list->head->prev = data;
    list->head = data;
    data->prev = NULL;
    pthread_mutex_unlock(&(list->mutex));
}

void removeElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&(list->mutex));

    if (data->prev != NULL) data->prev->next = data->next;
    if (data->next != NULL) data->next->prev = data->prev;
    if (list->head == data) list->head = data->next;

    free(data); // Free memory when element is removed

    pthread_mutex_unlock(&(list->mutex));
}

void destroyList(LinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T *curr = list->head, *next;
    while (curr != NULL) {
        next = curr->next;
        free(curr); // Free each element in the list
        curr = next;
    }

    pthread_mutex_destroy(&(list->mutex));
    free(list); // Finally, free the list itself
}
``` 

Note: For production quality code, you would need to handle allocation failures in all functions. This is a simplified example for demonstration purposes. Also, error handling and concurrency management can be improved by using atomic operations or other synchronization primitives where necessary. 

Please follow the given structure to design your library based on your requirements. You may add more features as per your specific needs.
']

