angular.module('myApp')
  .factory('DataRefreshService', ['$q', '$http', '$websocket', function ($q, $http, $websocket) {
    var cache = {}; // Cache to store the response data

    return {
      refreshFields: function(url, resourceId, fieldsToRefresh){
        // Create a promise that will be resolved with the refreshed field values.
        var deferred = $q.defer();

        if (cache[resourceId] && cache[resourceId].timestamp > Date.now() - 1000*60) {
          // If data is in cache and not older than 1 minute, resolve with cached data.
          deferred.resolve(fieldsToRefresh.map((fieldName) => ({[fieldName]: cache[resourceId][fieldName]})));
        } else {
          var apiPromise;

          if (url.indexOf('graphql') > -1) { // Check if GraphQL API
            apiPromise = this.callGraphQlApi(url, resourceId);
          } else if (url.indexOf('ws://') === 0 || url.indexOf('wss://') === 0){ // Check if WebSocket URL
            apiPromise = this.connectWebSocket(url, resourceId);
          } else { // Default to RESTful API
            apiPromise = $http({method: 'GET', url: `${url}/${resourceId}`});
          }

          apiPromise.then((response) => {
            var fieldValues = fieldsToRefresh.map((fieldName) => ({[fieldName]: response[fieldName]}));
            cache[resourceId] = {timestamp: Date.now(), ...fieldValues}; // Cache refreshed data
            deferred.resolve(fieldValues);
          }).catch((error) => {
            console.error('Error refreshing data', error); // Log error for troubleshooting
            if (cache[resourceId]) { // If cached data is available, resolve with it to maintain UI state
              deferred.resolve(fieldsToRefresh.map((fieldName) => ({[fieldName]: cache[resourceId][fieldName]})));
            } else { // Otherwise reject the promise and notify user/dev that there was an error
              deferred.reject('Error refreshing data, please try again later');
            }
          });
        }

        return deferred.promise;
      },

      callGraphQlApi: function(url, resourceId){ /* Implementation details not shown */},
      connectWebSocket: function(url, resourceId) { /* Implementation details not shown */}
    };
  }]);
