pthread_mutex_t lock;

// Function to insert a node at the beginning of a linked list
void insert(Node **head_ref, int new_data) {
    Node *new_node = (Node *) malloc(sizeof(Node)); // Allocate memory for new node

    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety

    if (!new_node) {
        printf("Memory allocation failed. Unable to insert.\n");
        return;
    }

    new_node->data  = new_data;
    new_node->next = (*head_ref);    
    (*head_ref)    = new_node;

    pthread_mutex_unlock(&lock); // Unlock the mutex
}

// Function to delete a node in a linked list by key
void deleteNode(Node **head_ref, int key) {
    Node* temp = *head_ref, *prev;

    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety

    if (temp != NULL && temp->data == key) {
        *head_ref = temp->next;
        free(temp);              
        return;
    }

    while (temp != NULL && temp->data != key) {
        prev = temp;
        temp = temp->next;
    } 

    if (temp == NULL) return; // If the node was not found in the list
    prev->next = temp->next;

    free(temp); // Free memory of the deleted node

    pthread_mutex_unlock(&lock); // Unlock the mutex
}

// Function to search a node by key in linked list
Node *search(Node *head, int x) {
    Node *current = head; 
    while (current != NULL) {
        if (current->data == x)
            return current; // If the node is found return it
        current = current->next;
    }

    return NULL; // If the node was not found in the list
}
``` 
This is just a simple pseudo code to implement doubly linked list with insertion, deletion and search functionality. You'll need to adapt it according to your requirements and add error handling mechanism as well.
