// Pseudo code to illustrate the structure of your application 
public class Application {
    private DataSource dataSource;
    private Authenticator authenticator;
    private Authorizer authorizer;
    private Cache cache;
    private Broker broker;

    public void updateResource(String resourceId, String userId, UpdateRequest request) {
        User user = authenticator.authenticate(userId);
        authorizer.authorize(user, resourceId);

        RetryTemplate retryTemplate = new RetryTemplate();
        retryTemplate.execute(() -> {
            dataSource.updateResource(resourceId, request);
            cache.invalidate(resourceId);
            broker.publishUpdateEvent(resourceId, request);
        });
    }

    public void deleteResource(String resourceId, String userId) {
        User user = authenticator.authenticate(userId);
        authorizer.authorize(user, resourceId);

        RetryTemplate retryTemplate = new RetryTemplate();
        retryTemplate.execute(() -> {
            dataSource.deleteResource(resourceId);
            cache.invalidate(resourceId);
            broker.publishDeleteEvent(resourceId);
        });
    }
}
```
