  const text = req.body.text; // assuming this is the incoming unstructured text data
  let booksFromApi = cache.get('books');

  if (!booksFromApi) {
    for(let i = 0; i < app.config.retryAttempts; i++){
      try{
        const response = await axios.get(app.config.bookApiUrl);
        booksFromApi = response.data;
        cache.set('books', booksFromApi, 60 * 60 * 24); // Cache for 24 hours
        break;
      } catch (err) {
        console.error(`Failed to get book names from API on attempt ${i+1}. Error: ${err}`);
      }
    }
  }

  const matchedBooks = text.match(/(\w*)/g).filter((word)=> app.config.bookNamesToMatch.includes(word));

  res.json({frequency: matchedBooks});
});

app.listen(3000, () => {
  console.log('Server is up on port 3000');
});
