using System;
using Polly;
using System.Net.Http;
using System.Threading.Tasks;

public class EmailService {
    private readonly HttpClient _httpClient;
    private AsyncPolicy retryPolicy = Policy
        .Handle<Exception>()
        .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

    public EmailService(HttpClient httpClient) {
        _httpClient = httpClient;
    }

    public async Task SendEmail(string email, string config) {
        await retryPolicy.ExecuteAsync(async () =>
        {
            var response = await _httpClient.PostAsJsonAsync("api/sendemail", new { Email = email, Config = config });

            if (!response.IsSuccessStatusCode && response.StatusCode == HttpStatusCode.TooManyRequests)
            {
                Console.WriteLine($"Rate limit exceeded. Retrying in 60 seconds...");
                await Task.Delay(TimeSpan.FromSeconds(60));
            } else if (!response.IsSuccessStatusCode) {
                throw new HttpRequestException($"Error sending email: {response.ReasonPhrase}");
            }
        });
    }
}
```
