```rust
use hyper::{Client, Url};
use std::fs;

pub async fn generatePEMCertificate(
    oauth_token: &str, 
    ca_url: &str, 
    private_key_path: &str, 
    certificate_path: &str) -> Result<(), Box<dyn std::error::Error>> {

    let client = Client::new();
    let url = Url::parse(&ca_url).map_err(|e| formatErr(e))?;

    // Send a request to the CA service with OAuth token in header.
    let response = client.get(url.clone()).await?;

    if !response.status().is_success() {
        return Err("Unable to fetch private key and certificate from CA".into());
    }

    // Read the body of the HTTP response as bytes.
    let body = hyper::body::to_bytes(response.into_body()).await?;

    // Assume the body contains the private key and certificate. 
    fs::write(private_key_path, &body[0..128])?; // Example for first half of bytes.
    fs::write(certificate_path, &body[128..])?; // Example for second half of bytes.

    Ok(())
}
```

