    public async Task<string> IntegrateNewWebsiteAsync(string directoryPath, string siteName, 
        string webConfigTemplatePath, string externalDependencyUrl, List<string> dependentServices, int timeoutInMinutes)
    {
        Stopwatch stopWatch = new Stopwatch();
        stopWatch.Start();

        try
        {
            // Validate directoryPath and other parameters
            if (!Directory.Exists(directoryPath)) return null;
            var webConfigFilePath = Path.Combine(directoryPath, "web.config");
            if (File.Exists(webConfigFilePath) && !ValidateWebConfig(webConfigFilePath, webConfigTemplatePath)) return null;

            // Retry with exponential backoff for transient failures
            var attempts = 0;
            while (stopWatch.ElapsedMinutes < timeoutInMinutes)
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempts))); // Exponential backoff

                    // Generate unique web.config file based on template and externalDependencyUrl
                    var newWebConfig = GenerateNewWebConfig(webConfigTemplatePath, dependentServices, externalDependencyUrl);

                    // Start website asynchronously without blocking other processes
                    await Task.Run(() => { /* Start Website */ });

                    return siteName;
                }
                catch (Exception ex) when (IsTransientError(ex))
                {
                    attempts++;
                    Logger.LogError($"Integration failed with {siteName}. Retrying... Attempt: {attempts}");
                }
            }
        }
        catch (Exception ex)
        {
            Logger.LogError($"Error while integrating website {siteName}: {ex.Message}", ex);
        }

        return null;
