typedef struct Node {
    unsigned long seq_num;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    CRC_INDICATION_REL8_TAG tag;
    struct Node* next;
} Node;

static Node* head = NULL; // Global variable to store the head of linked list
pthread_mutex_t lock; // Mutex for thread safety

void initialize() {
    pthread_mutex_init(&lock, NULL);
}

Node* createNode(unsigned long seq_num, NFAPI_CRC_INDICATION_PDU_T pdu, CRC_INDICATION_REL8_TAG tag) {
    Node* newNode = (Node*) malloc(sizeof(Node));

    if(!newNode) return NULL; // Handle memory allocation failure

    newNode->seq_num = seq_num;
    newNode->pdu = pdu;
    newNode->tag = tag;
    newNode->next = NULL;

    return newNode;
}

void insert(unsigned long seq_num, NFAPI_CRC_INDICATION_PDU_T pdu, CRC_INDICATION_REL8_TAG tag) {
    assert(seq_num != 0); // Handle invalid inputs

    Node* newNode = createNode(seq_num, pdu, tag);

    if(!newNode) return; // Handle memory allocation failure

    pthread_mutex_lock(&lock);

    if (head == NULL || head->seq_num > seq_num) { // Insert at the beginning of list
        newNode->next = head;
        head = newNode;
    } else {
        Node* current = head;

        while(current->next && current->next->seq_num < seq_num) 
            current = current->next; // Find the position to insert

        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void delete(unsigned long seq_num) {
    assert(seq_num != 0); // Handle invalid inputs

    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;

    if (temp && temp->seq_num == seq_num) { // Delete the head of list
        head = temp->next;
        free(temp);
    } else {
        while(temp && temp->seq_num != seq_num) {
            prev = temp;
            temp = temp->next;
        }

        if (temp == NULL) return; // Sequence number not found

        prev->next = temp->next; // Unlink the node from list
        free(temp); 
    }

    pthread_mutex_unlock(&lock);
}

Node* get(unsigned long seq_num) {
    assert(seq_num != 0); // Handle invalid inputs

    pthread_mutex_lock(&lock);

    Node* temp = head;

    while (temp && temp->seq_num != seq_num) 
        temp = temp->next; // Find the node with matching sequence number

    if(!temp) {
        pthread_mutex_unlock(&lock);
        return NULL; // Sequence number not found
    }

    Node* result = createNode(temp->seq_num, temp->pdu, temp->tag);

    pthread_mutex_unlock(&lock);

    return result; 
}
```
