["Here's a basic implementation of the library in C, which satisfies the requirements mentioned above:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct HashTable {
    pthread_mutex_t lock;
    Record** records;
    int size;
    int count;
} HashTable;

HashTable* create(int size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->records = (Record**)calloc(size, sizeof(Record*));
    if (!ht->records) {
        free(ht);
        return NULL;
    }

    ht->size = size;
    ht->count = 0;

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

int hashCode(int key, int size) {
    return key % size;
}

void insert(HashTable* ht, Record* record) {
    if (ht->count == ht->size) {
        // handle table full scenario here
        return;
    }

    pthread_mutex_lock(&ht->lock);

    int hashIndex = hashCode(record->key, ht->size);
    while (ht->records[hashIndex] != NULL && ht->records[hashIndex]->key != -1) {
        ++hashIndex;
        hashIndex %= ht->size;
    }

    ht->records[hashIndex] = record;
    ht->count++;

    pthread_mutex_unlock(&ht->lock);
}

Record* get(HashTable* ht, int key) {
    int hashIndex = hashCode(key, ht->size);

    while (ht->records[hashIndex] != NULL) {
        if (ht->records[hashIndex]->key == key) return ht->records[hashIndex];
        ++hashIndex;
        hashIndex %= ht->size;
    }

    return NULL;
}

void destroy(HashTable* ht) {
    for (int i = 0; i < ht->size; ++i) {
        if (ht->records[i] != NULL && ht->records[i]->key != -1) free(ht->records[i]);
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht->records);
    free(ht);
}
```
This is a basic implementation of the hash table and you will need to add error checking, logging, and other enhancements as per your needs. Also, this code assumes that each key is unique. If you have multiple records with the same key, you would have to modify the insert function accordingly. 

Remember that actual performance can vary depending on a number of factors such as memory layout, cache hit rate, thread scheduling etc., and may not be directly comparable between different systems or compilers. Therefore, always use your own judgement when making performance related decisions in real-world applications.
"]

