['Here is a basic structure of the `SecureRandomUtilities` class. Please note that this code only serves as an example. The full implementation would require more detailed design and planning including secure coding guidelines, proper error handling, and performance tuning based on specific use cases. 

```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Threading;
using System.Collections.Concurrent;
using Microsoft.Extensions.Logging;

public class SecureRandomUtilities : IDisposable
{
    private readonly ILogger<SecureRandomUtilities> _logger;
    private readonly ConcurrentQueue<string> _loggingQueue = new();
    private readonly Thread _loggingThread;
    private readonly RNGCryptoServiceProvider _cryptoServiceProvider = new();
    private bool _disposedValue;

    public SecureRandomUtilities(ILogger<SecureRandomUtilities> logger)
    {
        _logger = logger;
        // Start logging thread.
        _loggingThread = new Thread(() => ProcessLogQueue());
        _loggingThread.Start();
    }

    private void ProcessLogQueue()
    {
        while (true)
        {
            if (_loggingQueue.TryDequeue(out var log))
            {
                _logger.LogInformation("{log}", log);
            }
        }
    }

    public int GenerateRandomInteger()
    {
        byte[] randomNumber = new byte[4]; // 4 for int32
        _cryptoServiceProvider.GetBytes(randomNumber);
        var number = BitConverter.ToInt32(randomNumber, 0);

        // Add log data to the queue.
        _loggingQueue.Enqueue($"Generated random integer: {number} at {DateTime.Now}");

        return number;
    }

    public double GenerateRandomDouble()
    {
        byte[] randomNumber = new byte[8]; // 8 for double
        _cryptoServiceProvider.GetBytes(randomNumber);
        var number = BitConverter.ToDouble(randomNumber, 0);

        // Add log data to the queue.
        _loggingQueue.Enqueue($"Generated random float: {number} at {DateTime.Now}");

        return number;
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposedValue)
        {
            if (disposing)
            {
                _cryptoServiceProvider.Dispose();
            }

            _disposedValue = true;
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}
```

This code demonstrates a basic `SecureRandomUtilities` class that generates secure random integers and floating-point numbers using the RNGCryptoServiceProvider in .NET, which is designed to produce cryptographically strong random numbers. It also implements a simple logging mechanism using a queue and dedicated thread for processing log entries.

Please adapt this code according to your requirement and make sure it meets all security best practices. Also consider performance tuning based on specific use-cases.
']

