import asyncio
import aiohttp
import aioredis
import requests
from functools import lru_cache

class WebSocketDataIngestor:
    def __init__(self, websocket_url, redis_config):
        self.websocket_url = websocket_url
        self.redis_client = aioredis.RedisCluster(**redis_config)

    async def ingest_data(self):
        session = aiohttp.ClientSession()
        async with session.ws_connect(self.websocket_url) as ws:
            async for msg in ws:
                if msg.type == aiohttp.WSMsgType.TEXT:
                    data = msg.data  # process the incoming WebSocket data
                    await self.redis_client.rpush('queue', data)  # push to redis queue

    def start(self):
        asyncio.get_event_loop().run_until_complete(self.ingest_data())

