typedef struct {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} Array;

// Initialize an empty array
void initArray(Array *a, size_t initialSize) {
    a->size = 0;
    a->capacity = initialSize;
    a->data = malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Append an element to the end of array
void appendToArray(Array *a, NFAPI_CRC_INDICATION_PDU_T value) {
    if (a->size >= a->capacity) {
        a->capacity *= 2;
        a->data = realloc(a->data, a->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    a->data[a->size++] = value;
}

// Get an element by index
NFAPI_CRC_INDICATION_PDU_T getFromArray(Array *a, size_t index) {
    if (index >= a->size) {
        // Handle error - out of bounds
        return NULL; 
    }

    return a->data[index];
}
```
