    private readonly IProductService _productService;

    public ProductServiceWithCache(IDatabase database, IProductService productService)
    {
        _database = database;
        _productService = productService;
    }

    public async Task<IEnumerable<Product>> GetAll() 
    {
        var cachedResponse = await _database.StringGetAsync("products");

        if (!cachedResponse.IsNullOrEmpty) 
            return JsonConvert.DeserializeObject<IEnumerable<Product>>(cachedResponse);

