['Here's a simplified example of how you can tackle this problem in C using SDL2 for graphics and XML support. The code is quite complex due to the requirements. A full implementation would be extensive and beyond the scope of this platform. Note that this code does not cover all aspects of your request, but it provides a starting point:

```c
#include <SDL2/SDL.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct {
    int width;
    int height;
} Tile;

typedef struct {
    float x, y;
    int speed;
} Camera;

typedef struct {
    Tile* tiles;
    int numTiles;
    Camera camera;
} World;

World loadConfig(const char* configFile) {
    World world = {0};
    xmlDocPtr doc = xmlParseFile(configFile);

    if (doc == NULL) {
        fprintf(stderr, "Failed to parse configuration file\n");
        return world;
    }

    xmlNodePtr root = xmlDocGetRootElement(doc);
    for (xmlNodePtr node = root->children; node; node = node->next) {
        if (!xmlStrcmp(node->name, "tileSize")) {
            world.numTiles = atoi((char*) xmlNodeGetContent(node));
        } else if (!xmlStrcmp(node->name, "worldDimensions")) {
            char* token = strtok((char*) xmlNodeGetContent(node), ",");
            world.tiles = (Tile*) calloc(world.numTiles * world.numTiles, sizeof(Tile));
            for (int i = 0; i < world.numTiles * world.numTiles; ++i) {
                world.tiles[i].width = atoi(token);
                token = strtok(NULL, ",");
                world.tiles[i].height = atoi(token);
            }
        } else if (!xmlStrcmp(node->name, "cameraSpeed")) {
            world.camera.speed = atoi((char*) xmlNodeGetContent(node));
        }
    }

    xmlFreeDoc(doc);
    return world;
}

void updateCameraPosition(World* world) {
    // Update camera position based on user input or other factors
}

int main() {
    World world = loadConfig("config.xml");

    if (SDL_Init(SDL_INIT_VIDEO) != 0 ) {
        fprintf(stderr, "Failed to initialize SDL: %s\n", SDL_GetError());
        return 1;
    }

    while (!quit) {
        updateCameraPosition(&world);

        // Render code here...
    }

    free(world.tiles);
    SDL_Quit();
    return 0;
}
```
This is a simplified example and doesn't include all aspects of your requirements, but it should give you an idea of how to approach the problem in C using SDL2 for graphics and XML support. You would need to extend this code to handle errors correctly, add logging, unit testing, and so on.
