        .Handle<Exception>()
        .Or<WebException>()
        .AdvancedCircuitBreakerAsync(0.5, TimeSpan.FromSeconds(10), 2, TimeSpan.FromMinutes(1), () => Logger.Information("Circuit Breaker Opened"));

