class BufferHelper {
    constructor() {
        this.bufferList = [];
    }

    insertAfterOrAppend(target, str) {
        let targetIndex = this.bufferList.indexOf(target);

        if (targetIndex !== -1) {
            this.bufferList.splice(targetIndex + 1, 0, Buffer.from(str));
        } else {
            this.bufferList.push(Buffer.from(str));
        }
    }

