// ScalingTransformation.java in transformations package
public class ScalingTransformation implements Transformation {
    private final double scaleFactor;

    public ScalingTransformation(double scaleFactor) {
        this.scaleFactor = scaleFactor;
    }

    @Override
    public BufferedImage apply(BufferedImage image) {
        int width = (int)(image.getWidth() * scaleFactor);
        int height = (int)(image.getHeight() * scaleFactor);

        Image scaledImage = image.getScaledInstance(width, height, Image.SCALE_SMOOTH);
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics2D = result.createGraphics();
        graphics2D.drawImage(scaledImage, 0, 0, null);
        graphics2D.dispose();

        return result;
    }
}
```
