// Define your structure and any other necessary headers
typedef struct LTE_PHY_RX_FRAME {
    // Add members according to the data you need
} LTE_PHY_RX_FRAME;

// Define a resizable array type
typedef struct ResizableArray {
    int size; 
    int capacity; 
    LTE_PHY_RX_FRAME* arr; 
    pthread_mutex_t lock; // For thread safety
} ResizableArray;

// Function to initialize an array
void init(ResizableArray *a, int initialSize) {
   a->arr = (LTE_PHY_RX_FRAME *)malloc(initialSize * sizeof(LTE_PHY_RX_FRAME)); 
   a->size = 0; 
   a->capacity = initialSize; 
   pthread_mutex_init(&a->lock, NULL); // Initialize the mutex
}

// Function to add an element
void add(ResizableArray *a, LTE_PHY_RX_FRAME e) {
    pthread_mutex_lock(&a->lock);  // Lock before editing
    if (a->size == a->capacity) {
        a->capacity *= 2; 
        a->arr = realloc(a->arr, a->capacity * sizeof(LTE_PHY_RX_FRAME)); 
    }
    a->arr[a->size++] = e; // Add the element
    pthread_mutex_unlock(&a->lock); // Unlock after editing
}

// Function to delete an element (you may need to adjust this based on your specific needs)
void delete(ResizableArray *a, int index) {
   if(index >= a->size || index < 0){
      printf("Index out of bounds\n"); 
      return;
   }
    pthread_mutex_lock(&a->lock); // Lock before editing
    for (int i = index; i < a->size - 1; ++i) {
        a->arr[i] = a->arr[i + 1];
    }
    --a->size; 
    pthread_mutex_unlock(&a->lock); // Unlock after editing
}
```
