    pthread_mutex_destroy(&array->lock);
}

int addFrameToArray(FrameArray* array, LTE_PHY_RX_FRAME frame) {
    int err = 0;

    if (pthread_mutex_lock(&array->lock)) return -1;

    // check capacity and resize as needed
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2 + 1;
        LTE_PHY_RX_FRAME* newFrames = realloc(array->frames, newCapacity * sizeof(LTE_PHY_RX_FRAME));

        if (!newFrames) {
            err = -1; // out of memory
        } else {
            array->capacity = newCapacity;
            array->frames = newFrames;
        }
    }

    if (err == 0) {
        array->frames[array->count++] = frame;
    }

    pthread_mutex_unlock(&array->lock);
    return err;
}
