['This problem is quite complex and involves various aspects like dynamic configuration, integration with external systems, data validation, data storage and indexing, etc. Here's a high level overview of how to structure the code. 

```python
import concurrent.futures, requests
from elasticsearch import Elasticsearch
from configparser import ConfigParser
from schema import Schema
from retry import retry
from datetime import datetime

class DataIngestionPipeline:
    def __init__(self):
        self.config = ConfigParser()
        self.schema_validator = SchemaValidator()
        self.es = Elasticsearch()

    @retry(requests.exceptions.RequestException, tries=5, delay=1)
    def fetch_data(self, url):
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to get data from URL")

    @retry((Exception), tries=3, delay=1)
    def process_data(self, data):
        if self.schema_validator.validate(data):
            # Process the validated data here
            pass
        else:
            raise Exception("Data validation failed")

    @retry((Exception), tries=3, delay=1)
    def index_data(self, data):
        self.es.index(index="articles", body=data)

    def run(self):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            future_to_url = {executor.submit(self.fetch_data, url): url for url in self.config['sources']}
            for future in concurrent.futures.as_completed(future_to_url):
                url = future_to_url[future]
                try:
                    data = future.result()
                    self.process_data(data)
                    self.index_data(data)
                except Exception as exc:
                    print('%r generated an exception: %s' % (url, exc))
```

Please note that this is a simplified example and doesn't include all the detailed aspects mentioned in your problem statement. Also, it assumes that you have setup the necessary modules/packages like `schema`, `retry`, `elasticsearch` etc correctly.

