```
2) A simple in-memory LRU cache using `unordered_map`:

```cpp
#include <iostream>
#include <list>
#include <unordered_map>

using namespace std;

class LRUCache {
private:
    int cap;
    list<pair<int, int>> lruList;
    unordered_map<int, list<pair<int, int>>::iterator> keyNodeMap;

public:
    LRUCache(int capacity) {
        cap = capacity;
    }

    int get(int key) {
        if (keyNodeMap.find(key) == keyNodeMap.end()) return -1;

        auto it = keyNodeMap[key];
        lruList.splice(lruList.begin(), lruList, it);

        return it->second;
    }

    void put(int key, int value) {
        if (get(key) != -1) {
            keyNodeMap[key]->second = value;
            return;
        }

        if (lruList.size() == cap) {
            auto toDelete = lruList.back();
            lruList.pop_back();
            keyNodeMap.erase(toDelete.first);
        }

        lruList.push_front({key, value});
        keyNodeMap[key] = lruList.begin();
    }
};
```

Remember to install `libcurl-dev` and `libcurl4-openssl-dev` in Linux before compiling the code using g++:

```bash
sudo apt update
sudo apt install libcurl4-openssl-dev libcurl4-gnutls-dev
```

