public async Task<IEnumerable<DeploymentResult>> DeployAndScaleWebApp(List<WebAppSpecification> webApps, CancellationToken cancellationToken)
{
    var results = new ConcurrentBag<DeploymentResult>();
    var tasks = new List<Task>();
    foreach (var webApp in webApps)
    {
        tasks.Add(DeployAndScaleWebApplicationAsync(webApp, results, cancellationToken));
    }

    await Task.WhenAll(tasks);

    return results;
}

private async Task DeployAndScaleWebApplicationAsync(WebAppSpecification webApp, ConcurrentBag<DeploymentResult> results, CancellationToken cancellationToken)
{
    try
    {
        var tcs = new TaskCompletionSource<bool>();
        using (cancellationToken.Register(() => tcs.TrySetCanceled()))
        {
            // Deploy and scale web application logic here

            if (!tcs.Task.IsCompleted)
                await tcs.Task;
        }
    }
    catch (Exception ex)
    {
        results.Add(new DeploymentResult 
