void processStreamLogs(int sockFd, LogConfig *logConfig, int asyncFlag) {
    // Validate inputs, check if socket is connected and handle timeouts
    if (sockFd < 0 || logConfig == NULL) {
        return;
    }

    char* buffer = malloc(sizeof(char)*logConfig->bufferSize);
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        // Read from socket into buffer
        int bytesRead = recv(sockFd, buffer, logConfig->bufferSize, 0);

        if (bytesRead <= 0) {
            break;
        }

        // Apply deduplication strategy and add to the logs queue
        pthread_mutex_lock(&lock);
        sendToDistributedLoggingSystem(buffer);
        pthread_mutex_unlock(&lock);
    }

    free(buffer);
}
