#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static Node* head = NULL;

void add(NFAPI_CRC_INDICATION_PDU_T value) {
    Node* newNode = (Node*) malloc(sizeof(Node));

    pthread_mutex_lock(&lock);
    if(!newNode){
        // handle allocation failure gracefully, alert the application 
        return;
    }

    newNode->data = value;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* get(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    while (temp != NULL) {
        if (temp->data.RNTI == RNTI) {
            pthread_mutex_unlock(&lock);
            return &(temp->data);
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);

    // handle RNTI not found 
    return NULL;
}
```

In this library, we are using a simple linked list for data storage. We have added thread safety by wrapping our operations in mutex locks to prevent race conditions when accessing the list concurrently from different threads. This is just a basic example and doesn't cover all your requirements. For full-fledged production quality code, you would need much more than this including extensive error checking, testing, documentation, performance optimization, thread safety, and integration with other systems as per your specifications.
