typedef struct Algorithm {
    char* name;
    void (*hashFunction)(const void*, size_t, void*);
    // other algorithm properties...
} Algorithm;

// Global variables
pthread_mutex_t lock;
Algorithm** algorithms;
size_t numOfAlgorithms = 0;

void initialize() {
    pthread_mutex_init(&lock, NULL);
    algorithms = malloc(sizeof(Algorithm*)); // initial capacity
}

// Dynamically retrieve and manage a list of cryptographic algorithms
void addAlgorithm(char* name, void (*hashFunction)(const void*, size_t, void*)) {
    pthread_mutex_lock(&lock);

    Algorithm* newAlgo = malloc(sizeof(Algorithm));
    newAlgo->name = name;
    newAlgo->hashFunction = hashFunction;

    algorithms[numOfAlgorithms++] = newAlgo;
    algorithms = realloc(algorithms, (numOfAlgorithms + 1) * sizeof(Algorithm*)); // Reallocate memory when necessary

    pthread_mutex_unlock(&lock);
}

// Thread safe function to retrieve an algorithm by name
Algorithm* getAlgorithmByName(char* name) {
    for (size_t i = 0; i < numOfAlgorithms; ++i) {
        if (strcmp(algorithms[i]->name, name) == 0) {
            return algorithms[i];
        }
    }

    return NULL; // Algorithm not found
}

