['Here is a basic C++ implementation of your requirements using std::mt19937 as the random number generator from the Mersenne Twister engine, thread-safe and efficient concurrent access via std::mutex. It can be extended for distributed systems with external configuration service (not implemented here) and error handling strategies.

```cpp
#include <random>
#include <vector>
#include <stdexcept>
#include <mutex>

class RandomEngine {
public:
    class MersenneTwisterService {
        std::mt19937 gen;
        std::mutex mtx; // for thread-safe access

    public:
        MersenneTwisterService() : gen(std::random_device{}()) {}

        void setSeed(const std::string& uniqueId) {
            size_t hash = std::hash<std::string>{}(uniqueId);
            std::lock_guard<std::mutex> lock(mtx); // thread-safe locking
            gen.seed(static_cast<unsigned int>(hash));
        }

        int getRandom(int min, int max) {
            if (min > max) throw std::invalid_argument("min should be less than or equal to max");
            std::lock_guard<std::mutex> lock(mtx); // thread-safe locking
            return std::uniform_int_distribution<>{min, max}(gen);
        }

        double getContinuous(double min, double max) {
            if (min > max) throw std::invalid_argument("min should be less than or equal to max");
            std::lock_guard<std::mutex> lock(mtx); // thread-safe locking
            return std::uniform_real_distribution<>{min, max}(gen);
        }

        std::vector<int> generateSequence(size_t count, int min, int max) {
            if (count == 0 || min > max) throw std::invalid_argument("Invalid arguments");
            std::lock_guard<std::mutex> lock(mtx); // thread-safe locking
            std::vector<int> res;
            for (size_t i = 0; i < count; ++i) {
                res.push_back(getRandom(min, max));
            }
            return res;
        }
    };
};
``` 

This code block is a basic implementation and should be adapted as per the requirements. For instance, the `std::mt19937` seed can be set with another RNG or perhaps from an external service that provides unique identifiers. Error handling could be more comprehensive depending on the context and requirements of your system.
']

