```jsx
class ScriptLoader {
  constructor() {
    this.cache = window.sessionStorage; // You can use localStorage instead if needed
    this.fallbackScripts = [];
  }

  load(script) {
    const scriptTag = document.createElement('script');
    return new Promise((resolve, reject) => {
      scriptTag.onload = () => resolve();
      scriptTag.onerror = (err) => reject(err);

      // Check if already loaded or in cache
      if (!this._shouldLoadScript(script)) {
        return this._getFallbackScripts();
      }

      // Load from external URL
      if (script.url && !script.content) {
        scriptTag.src = script.url;

        // Check for cached content 
        const cachedContent = this.cache.getItem(script.url);
        if (cachedContent) {
          scriptTag.textContent = cachedContent;
        } else {
          document.head.appendChild(scriptTag);
        }
      // Load from inline content
      } else if (!script.url && script.content) {
        this.cache.setItem(script.id, script.content); // Cache loaded scripts

        // Append to DOM after validation and sanitization
        scriptTag.textContent = this._sanitizeScript(script.content); 
        document.head.appendChild(scriptTag);
      } else {
        reject('Invalid script: either URL or content must be provided');
      }
    });
  }

  _shouldLoadScript() {
    // Your custom logic for conditional loading based on user preferences, browser capabilities and device types goes here.
    return true;
  }

  _getFallbackScripts() {
    return Promise.allSettled(this.fallbackScripts.map((script) => this.load(script)));
  }

  _sanitizeScript(content) {
    // Sanitization function to prevent XSS attacks. This is a simplified example, and more complex sanitizations might be required in production.
    return content.replace(/<(\/|\\)?script>/g, '');
  }
}
```
This code provides basic functionality for loading scripts dynamically asynchronously. It's modular so it can be easily integrated into a larger system or extended with additional features. However, the actual implementation would require more thorough testing and design decisions based on specific requirements and constraints.
