["Creating a full-fledged C++ application that meets all these requirements is beyond the scope of this platform, but I can provide an example of how you might structure your code with some key elements addressed to address each constraint. 

```C++
#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
// Include necessary libraries, such as cpr (for HTTP requests), nlohmann/json (for JSON handling) etc.

class NetworkMonitor {
    std::vector<std::thread> threads;
    bool done;
    std::queue<std::string> work_queue;
    std::mutex m;
    std::condition_variable cv;

public:
    NetworkMonitor() : done(false) { }
    ~NetworkMonitor() { 
        done = true;
        for (auto& th : threads) {
            if(th.joinable()) th.join();
        }
    }

    void worker_thread() {
        while (!done) {
            std::unique_lock<std::mutex> lock(m);
            cv.wait(lock, [&]{ return !work_queue.empty() || done; });

            if(!work_queue.empty()) {  // work available
                std::string item = work_queue.front();
                work_queue.pop();

                lock.unlock();  // Unlock for network calls which may take time
                /* Make HTTP request here and handle error using the provided strategies */
            }
        }
    }

    void start(size_t thread_count = 1) {
        try {
            for (size_t i=0; i<thread_count; ++i)
                threads.push_back(std::thread(&NetworkMonitor::worker_thread, this));
        } catch (...) { done = true; throw; }
    }

    void append_work(const std::string& item) {
        if (done) return;

        std::lock_guard<std::mutex> lock(m);
        work_queue.push(item);
        cv.notify_one();
    }
};
```

This is a basic example of how you can manage your worker threads to ensure concurrent monitoring while minimizing latency and resource contention. 

However, this code only covers the producer-consumer model and error handling, for full implementation addressing all constraints you will need many more components including:
