#include <string.h>

// This is a stub for the decompression and parsing functions, which will depend on your specific requirements and library choices.
static bool decompress(const char* filepath, const char* format) { return true; }
static int parse_json(char* resource) { return 0; }

SafeResourceBundle* init_bundle(const char* filepath, const char* format) {
    if (!decompress(filepath, format)) {
        return NULL; // Error occurred during decompression.
    }

    SafeResourceBundle* safe_bundle = malloc(sizeof(SafeResourceBundle));
    if (safe_bundle == NULL) {
        return NULL; // Memory allocation failed.
    }

    char* resource = /* Load the decompressed data */;
    int count = parse_json(resource);
    if (count < 0) {
        free(resource);
        free(safe_bundle);
        return NULL; // Error occurred during parsing.
    }

    safe_bundle->bundle = malloc(sizeof(ResourceBundle));
    if (safe_bundle->bundle == NULL) {
        free(resource);
        free(safe_bundle);
        return NULL; // Memory allocation failed.
    }

    safe_bundle->bundle->resource = resource;
    safe_bundle->bundle->count = count;
    pthread_mutex_init(&safe_bundle->lock, NULL); // Initialize mutex for thread safety.
    return safe_bundle;
}

void free_bundle(SafeResourceBundle* safe_bundle) {
    if (safe_bundle == NULL) {
        return;
    }

    pthread_mutex_lock(&safe_bundle->lock); // Lock mutex to ensure thread safety.
    if (safe_bundle->bundle != NULL && safe_bundle->bundle->resource != NULL) {
        free(safe_bundle->bundle->resource);
        free(safe_bundle->bundle);
    }
    pthread_mutex_unlock(&safe_bundle->lock); // Unlock mutex.

    pthread_mutex_destroy(&safe_bundle->lock); // Destroy the mutex.
    free(safe_bundle);
}

int get_count(SafeResourceBundle* safe_bundle) {
    if (safe_bundle == NULL || safe_bundle->bundle == NULL) {
        return -1;
    }

    pthread_mutex_lock(&safe_bundle->lock); // Lock mutex to ensure thread safety.
    int count = safe_bundle->bundle->count;
    pthread_mutex_unlock(&safe_bundle->lock); // Unlock mutex.

    return count;
}
```

This is a high-level overview and does not include error handling, resource management, or integration with cloud storage services, among other features that would need to be added in a production environment. Additionally, this code assumes you're using the pthread library for thread safety - if you're working in a different environment (e.g., Windows), you may need to use another method of managing threads and synchronization.
