void* process_csv(void *arg) {
    ThreadArgs* args = (ThreadArgs*) arg;

    /* Open CSV File */
    FILE *fp = fopen(args->csv_file, "r");
    if(fp == NULL){
        printf("Failed to open file: %s\n", args->csv_file);
        pthread_exit(NULL);
    }

    /* Read and Process CSV */
    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // process line...
    }

    /* Close File */
    fclose(fp);

    pthread_exit(NULL);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        printf("Usage: %s <csv-file> <api-key>\n", argv[0]);
        return 1;
    }

    /* Initialize libcurl */
    curl_global_init(CURL_GLOBAL_DEFAULT);

    ThreadArgs args = {argv[1], argv[2]};

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_csv, &args) != 0){
        printf("Failed to create thread.\n");
        return 1;
    }

    /* Wait for threads */
    pthread_join(thread, NULL);

    /* Cleanup libcurl */
    curl_global_cleanup();

    return 0;
}
