However, I can provide some code snippets or examples of how certain parts could look like:

1) A thread-safe random number generator with adjustable range:

```csharp
public class ThreadSafeRandom
{
    private static Random _global = new Random();

    [ThreadStatic] 
    private static Random _local;

    public double NextDouble(double min, double max)
    {
        if (_local == null)
        {
            lock(_global)
                if (_local == null)
                    _local = new Random(_global.Next());
        }

        return _local.NextDouble() * (max - min) + min;
    }
}
```
2) Using a rate limiting mechanism: 

A simple token bucket algorithm could be used to manage load and ensure that no more than the desired throughput is generated:

```csharp
public class TokenBucketRateLimiter
{
    private long lastFillTime;
    private double tokensPerMilli;
    private long capacity;
    private long availableTokens;

    public TokenBucketRateLimiter(long maxRequests, TimeSpan timeWindow) 
    {
        this.tokensPerMilli = (double)maxRequests / timeWindow.TotalMilliseconds;
        this.capacity = maxRequests;
        this.lastFillTime = GetCurrentTime();
    }

    public bool TryConsume() 
    {
        RefillTokensIfNeeded();

        if(availableTokens > 0)
        {
            --availableTokens;
            return true;
        }
        else
            return false;
    }

    private void RefillTokensIfNeeded() 
    {
        long currentTime = GetCurrentTime();

        if(currentTime > lastFillTime) 
        {
            long numberOfMillisElapsed = currentTime - lastFillTime;
            long newTokens = (long)(numberOfMillisElapsed * tokensPerMilli);

            availableTokens = Math.Min(capacity, availableTokens + newTokens);
            lastFillTime = currentTime;
        }
    }

    private long GetCurrentTime() 
    {
        return DateTime.Now.Ticks / TimeSpan.TicksPerMillisecond;
    }
}
```
