        if (cachedPreferences != null) return cachedPreferences;

        var preferencesFromDataStore = 
            await _dataStore.GetUserPreferenceAsync(userId, _configurationApi.CacheTimeout);

        await _cachingLayer.SetValueAsync(userId, preferencesFromDataStore);

        return preferencesFromDataStore;
    }

    public async Task UpdateUserPreferenceAsync(string userId, UserPreference newPreferences)
    {
        var updatedPreferences = 
            await _dataStore.UpdateUserPreferenceAsync(userId, 
                                                       _identityProvider.Encrypt(newPreferences));

        await _cachingLayer.SetValueAsync(userId, updatedPreferences);
    }

    public async Task DeleteUserPreferenceAsync(string userId)
    {
        await _dataStore.DeleteUserPreferenceAsync(userId);
        await _cachingLayer.InvalidateCacheAsync(userId);
    }
}
