import retry from 'async-retry';
// ... import other dependencies as needed

const app = express();
app.use(express.json()); // for parsing application/json

let cache = createClient({ url: 'redis://alice:foobared@awesome.redis.server:6380' });
cache.on('error', (err) => console.log('Redis Client Error', err));
(async () => await cache.connect())();
// ... setup other connections, middleware, routes, etc. as needed

app.get('/api/configs/:tenantId', async (req, res) => {
  const tenantId = req.params.tenantId;

  let config;
  try {
    // Try to get the config from cache first
    config = await cache.get(`config-${tenantId}`);

    if (!config) {
      // If not in cache, fetch it from external service with retry and backoff strategy
      config = await retry(async (bail, attempt) => {
        try {
          const response = await axios.get(`https://external-service/${tenantId}/config`);

          // If successful, set it in the cache with appropriate TTL
          cache.set(`config-${tenantId}`, response.data, { PX: 10 * 60 * 1000 }); // expires in 10 minutes
          return response.data;
        } catch (err) {
          if (attempt > 5) bail(err); // If failed more than 5 times, stop trying

          const delay = attempt * 1000 + Math.random() * 500; // Backoff logic: linear increasing timeouts up to 6 seconds
          return new Promise((resolve) => setTimeout(() => resolve(err), delay));
        }
      });
    }

    res.json({ config, errors: [] }); // Return the fetched (or cached) config and any potential validation errors
  } catch (error) {
    // If all retries failed or some other error, return an error response with a fallback config
    res.status(500).json({ config: {}, errors: [{ message: 'Failed to fetch configuration' }] });
  }
});

// ... other routes and middleware as needed (e.g., for updating configurations)

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

