["This task is complex and requires a comprehensive understanding of JavaScript programming with asynchronous file operations. Here's a simplified skeleton of how you might approach this problem using Node.js streams. This does not include all the mentioned operational constraints but it gives an idea on how to start such pipeline:

```javascript
const fs = require('fs');
const cloudStorageService = require('cloud-storage-service');
const paymentGateway = require('payment-gateway');
const logger = require('logger-service');
const stream = require('stream');
const util = require('util');

class Pipeline extends stream.Transform {
    constructor(options) {
        super(options);
        this.totalAmount = 0;
        this.fileCount = 0;
    }

    _transform(chunk, encoding, callback) {
        const data = JSON.parse(chunk.toString());
        paymentGateway.validateTransaction(data).then(result => {
            if (result.status === 'success'){
                this.totalAmount += result.amount;
            }
            logger.log('info', `Processed file: ${this.fileCount}, Total Amount: ${this.totalAmount}`);
            callback();
        }).catch(error => {
            logger.log('error', `Error processing file: ${this.fileCount}`, error);
            callback(); // continue with next file 
        });
    };

    _flush(callback) {
        logger.log('info', `Final Total Amount: ${this.totalAmount}`);
        callback();
    }
}

async function processFilesInDirectory(dirPath, progressCallback){
    try{
        const files = await cloudStorageService.getFilesFromDir(dirPath);
        let processedFileCount = 0;

        for (const file of files) {
            fs.createReadStream(file.path)
                .pipe(new Pipeline())
                .on('finish', () => {
                    progressCallback((++processedFileCount / files.length * 100).toFixed(2)); // update progress percentage
                });
        }        
    } catch (error){
        logger.log('error', 'Error processing directory', error);
    }
}
```
