pub trait SecureHttpClient {
    fn createSecureHttpClient(&self, url: String, cert_validation: bool, tls_version: Option<String>) -> Result<Box<Self>>;
}

struct HttpClientService {}
impl SecureHttpClient for HttpClientService {
    fn createSecureHttpClient(&self, mut url: String, cert_validation: bool, tls_version: Option<String>) -> Result<Box<Self>, &'static str> {
        if url.is_empty() { return Err("Url is empty") }

        // Validate URL and handle other inputs.
        match url.parse::<Uri>() {
            Ok(_) => (),
            Err(_) => return Err("Invalid Url"),
        }

        let client = reqwest::Client::builder()
            .danger_accept_invalid_certs(cert_validation)
            // Set up TLS version enforcement.
            .danger_accept_invalid_hostnames(tls_version.unwrap_or_default())
            .build().map_err(|e| {
                error;
            })?;

        Ok(Box::new(client))
    }
}
```
