```python
# High Level Design - Python Library
import asyncio
import hashlib
from botocore.exceptions import BotoCoreError, NoCredentialsError
import boto3
from io import BytesIO

class HashComputer:
    def __init__(self):
        self.hash_algos = {
            'md5': hashlib.mdx(),
            'sha256': hashlib.sha256()
        }

    async def compute_file_hashes(self, file_locations, logger=None):
        tasks = []

        for location in file_locations:
            tasks.append(asyncio.create_task(compute_hash(location, self.hash_algos, logger)))

        await asyncio.gather(*tasks)

    # Streaming from S3 to compute hashes asynchronously
    async def compute_hash(self, location, hash_algos, logger=None):
        try:
            if 's3://' in location:
                s3 = boto3.client('s3')
                bucket_name, key = parse_s3_uri(location)

                response = await asyncio.to_thread(s3.get_object, Bucket=bucket_name, Key=key)

                for algo in hash_algos:
                    compute_hash_in_chunks(response['Body'].read(), algo)

            else:  # Local file system
                with open(location, 'rb') as f:
                    for algo in hash_algos:
                        compute_hash_in_chunks(f.read(), algo)

        except NoCredentialsError:
            if logger:
                logger.error("No AWS credentials found.")

        except BotoCoreError as e:
            if logger:
                logger.error("Boto3 error occurred: {e}")

    def compute_hash_in_chunks(self, file, hash_algo):
        for chunk in iter(lambda: file.read(4096), b''):
            hash_algo.update(chunk)
```
This is a high-level design of how you could create an asynchronous Python library to compute MD5 and SHA-256 hashes from files stored locally or in AWS S3 using boto3. The implementation is missing several important parts such as error handling, logging, testing, etc. Also, you would need to adapt this design according to your project's requirements and constraints.
