using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Newtonsoft.Json;

public class UpdateMiddleware
{
    private readonly RequestDelegate _next;

    public UpdateMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context, CMSApiClient apiClient)
    {
        if (context.Request.Method == HttpMethods.Post && context.Request.Path.Value.StartsWith("/update"))
        {
            var requestBody = await new StreamReader(context.Request.Body).ReadToEndAsync();
            dynamic data = JsonConvert.DeserializeObject<dynamic>(requestBody);

            string pageSectionId = (string)data?.pageSectionId;
            string elementId = (string)data?.elementId;
            string newHtmlContent = (string)data?.newHtmlContent;

            if (!IsValidInput(pageSectionId, elementId, newHtmlContent))
            {
                context.Response.StatusCode = 400; // Bad Request
                return;
            }

            try
            {
                await apiClient.UpdateElementAsync(pageSectionId, elementId, newHtmlContent);
                await _next(context);
            }
            catch (HttpRequestException ex) when (ex.StatusCode == HttpStatusCode.ServiceUnavailable)
            {
                // Handle temporary outage
                context.Response.StatusCode = 503; // Service Unavailable
            }
        }
    }

    private bool IsValidInput(string pageSectionId, string elementId, string newHtmlContent)
    {
        // Implement your validation logic here
        return !String.IsNullOrEmpty(pageSectionId) && 
               !String.IsNullOrEmpty(elementId) && 
               !String.IsNullOrEmpty(newHtmlContent);
    }
}

public static class UpdateMiddlewareExtensions
{
    public static IApplicationBuilder UseUpdateMiddleware(this IApplicationBuilder builder)
    {
        return builder.UseMiddleware<UpdateMiddleware>();
    }
}
```
