However, here's a skeleton of how you can begin to structure your solution:

```javascript
const express = require('express');
const app = express();
const fs = require('fs');
const util = require('util');
const readdir = util.promisify(fs.readdir);
const execa = require('execa');
const packageJson = require('./package.json');

app.get('/load', async (req, res) => {
  try {
    const depthLimit = req.query.depthLimit || 10;
    await loadModules('path/to/modules', depthLimit);
    res.send('Modules loaded successfully');
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

async function loadModules(directory, depth) {
  if (depth === 0) return;

  const files = await readdir(directory);

  for (const file of files) {
    const fullPath = `${directory}/${file}`;
    const stat = fs.statSync(fullPath);

    if (stat.isDirectory()) {
      await loadModules(fullPath, depth - 1);
    } else if (/\.js$/.test(file)) {
      require(fullPath); // This will execute the module and any dependencies it has
    }
  }
}

async function installDependencies() {
  const dependencies = Object.entries(packageJson.dependencies).map(([name, version]) => `${name}@${version}`).join(' ');
  await execa('npm', ['install', dependencies]);
}
```
This is a simple Express server that loads JavaScript files from a specified directory and its subdirectories. It uses the `fs` module to read directories and files, and the `execa` module to execute shell commands (in this case, it's used to install npm packages). Note that this doesn't include all of your requirements, but it should give you a starting point.
"]

