```python
import redis
from random import randint
import threading
import logging
import time

# Logging setup
logging.basicConfig(filename='app.log', filemode='w', format='%(name)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class Record:
    def __init__(self, value_range):
        self.offset = None
        self.key = None
        self.value = randint(0, value_range)

    def allocate(self, offsets, keys):
        with threading.Lock():  # Fine-grained locking
            while True:
                try:
                    self.offset = offsets.blpop()[1]
                    break
                except redis.exceptions.TimeoutError:
                    time.sleep(0.5)  # Non-blocking algorithm

            self.key = keys.spop()  # Consensus mechanism for key uniqueness

class DataSource:
    def __init__(self):
        self.redis_client = redis.Redis(host='localhost', port=6379, db=0)

    def fetch_offsets(self, data_source_key):  # Handling network latency
        return self.redis_client.lrange(data_source_key + '_offset', 0, -1)

    def fetch_keys(self, data_source_key):  # Potential failures gracefully handled
        try:
            return self.redis_client.smembers(data_source_key + '_key')
        except redis.exceptions.ConnectionError:
            logger.error("Failed to connect to Redis")

class DistributedMemoryManagementSystem:
    def __init__(self, value_range):
        self.value_range = value_range
        self.data_source = DataSource()

    def allocate_record(self, data_source_key):
        record = Record(self.value_range)
        offsets = self.data_source.fetch_offsets(data_source_key)
        keys = self.data_source.fetch_keys(data_source_key)
        try:
            record.allocate(offsets, keys)
            return record
        except Exception as e:
            logger.error("Failed to allocate and initialize record", exc_info=True)
```

