#include <iostream>
#include <forward_list>
#include <string>

void insertAfter(std::forward_list<std::string>& list, const std::string& findStr, const std::string& insertStr) {
    bool inserted = false;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == findStr) {
            it = list.insert_after(it, insertStr);
            inserted = true;
            break;
        }
    }

    if (!inserted) {  // String not found in the list
        list.push_front(insertStr);
    }
}

int main() {
    std::forward_list<std::string> myList = {"Apple", "Banana", "Cherry"};
    insertAfter(myList, "Banana", "Orange");  // After Banana, we have Orange
    for (const auto& str : myList) {
        std::cout << str << ' ';  // Outputs: Apple Banana Orange Cherry
    }

    return 0;
}
```
