            self.modules.append(module)

    def start_prometheus_server(self):
        threading.Thread(target=start_http_server, args=(8000,)).start()

class BaseModule:
    def __init__(self, name):
        self.name = name
        self.blueprint = Blueprint(name, __name__)

    def add_endpoint(self, endpoint=None, endpoint_name=None, handler=None, methods=['GET']):
        self.blueprint.add_url_rule(endpoint or f'/{endpoint_name}', endpoint_name, handler, methods=methods)

class DataSourceModule(BaseModule):
    def __init__(self, name, data_source):
        super().__init__(name)
        self.data_source = data_source

class ProcessingStageModule(BaseModule):
    def __init__(self, name, processing_stage):
        super().__init__(name)
        self.processing_stage = processing_stage
```
