[ApiController]
[Route("api/integers")]
public class IntegerManagementController : ControllerBase
{
    private readonly ConcurrentDictionary<string, int> _dataStore = new ConcurrentDictionary<string, int>();
    private readonly IDatabase _cache;
    private readonly IConfiguration _configuration;

    public IntegerManagementController(IConnectionMultiplexer redis, IConfiguration configuration)
    {
        _cache = redis.GetDatabase();
        _configuration = configuration;
    }

    [HttpPost]
    public async Task<IActionResult> Post([FromBody] int value)
    {
        var key = GenerateKey(value);
        await _cache.StringSetAsync(key, value); // Store in cache asynchronously
        _dataStore[key] = value; // Store in local data store

        return Ok();
    }

    [HttpGet("{id}")]
    public async Task<IActionResult> Get(string id)
    {
        if (!_dataStore.TryGetValue(id, out var value))
        {
            // Retry policy for fetching data from external system with exponential backoff
            var retryPolicy = Policy
                .Handle<ExternalSystemException>()
                .WaitAndRetryAsync(_configuration.GetSection("Polly:Retries").Value, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)));

            await retryPolicy.ExecuteAsync(async () => 
            {
                value = await FetchDataFromExternalSystem(id); // Simplified method to fetch data from external system

                _cache.StringSet(id, value); // Update cache with fetched data
                _dataStore[id] = value; // Update local data store with fetched data
