        perror("Failed to open error log file");
        exit(1);
    }

    time_t now;
    time(&now);
    char* timeString = ctime(&now);
    timeString[strlen(timeString)-1] = 0; // Remove newline.

    fprintf(logfile, "[%s] %s\n", timeString, message);
    fclose(logfile);
}
