public class HashingService : IHashingService
{
    private readonly ILogger<HashingService> _logger;
    private readonly IConnectionMultiplexer _redis;
    private readonly IAuthenticationApiClient _authenticationApiClient;

    public HashingService(ILogger<HashingService> logger, IConnectionMultiplexer redis, IAuthenticationApiClient authenticationApiClient)
    {
        _logger = logger;
        _redis = redis;
        _authenticationApiClient = authenticationApiClient;
    }

    public async Task<string> GenerateMD5Hash(string input, string userToken)
    {
        try
        {
            if (!await _authenticationApiClient.ValidateAsync(userToken))
                return "Invalid token";

            var cache = _redis.GetDatabase();
            var cachedResult = await cache.StringGetAsync($"MD5:{input}");
            if (cachedResult.HasValue)
                return cachedResult;

            using var md5 = MD5.Create();
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            string hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            await cache.StringSetAsync($"MD5:{input}", hash, TimeSpan.FromMinutes(5)); // Persistent Cache Entry
            _logger.LogInformation($"Generated MD5 Hash for {input}: {hash}");

            return hash;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to generate MD5 hash");
            throw;
        }
    }

    // Similarly implement SHA256 hash generation and other hashing algorithms
}
