    unsigned char key[SHA_DIGEST_LENGTH];

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Error handling
        return NULL;
    }

    SHA1((unsigned char*)password, strlen(password), key);

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
