#include <openssl/evp.h>
#include <openssl/sha.h>
#include <cstring>

// Function to initialize an AES-256-CBC cipher with a given password
EVP_CIPHER_CTX *InitAES256CBCCipher(const char* password) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[SHA_DIGEST_LENGTH]; // Output length of SHA1 is 20 bytes (160 bits)
    unsigned char iv[EVP_MAX_IV_LENGTH]; // Max IV length defined by OpenSSL

    ctx = EVP_CIPHER_CTX_new();
    if(ctx == nullptr) {
        throw std::runtime_error("Error creating cipher context.");
    }

    // Generate encryption key from password using SHA1
    unsigned char* tempKey = new unsigned char[strlen(password) + 1];
    memcpy(tempKey, password, strlen(password));
    tempKey[strlen(password)] = '\0';

    SHA1(tempKey, strlen((char*)tempKey), key); // 20 bytes (160 bits) key generated from SHA1
    delete [] tempKey;

    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha1(), nullptr, tempKey, strlen((char*)tempKey), 1, iv, key); // Generate IV and Key from password using SHA1

    if(!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key, iv)) {
        throw std::runtime_error("Error initializing cipher context.");
    }

    return ctx; // Return the initialized cipher context
}
```
This code creates a new OpenSSL EVP_CIPHER_CTX object to hold the encryption context. It then generates an AES 256-bit key and IV using a SHA1 hash of the password. Finally, it initializes the encryption context with these keys. The function returns a pointer to the initialized cipher context for further use in encryption operations.

