import java.util.*;

public class MediaMetadataProcessor {
    private static final Logger logger = LoggerFactory.getLogger(MediaMetadataProcessor.class);

    // Configurable options
    private int concurrencyLevel;
    private ResolutionStrategy resolutionStrategy;
    private boolean logDetails;
    private int maxRetries;
    private List<String> supportedFormats;

    // Queue to manage incoming media files
    private BlockingQueue<File> fileQueue = new ArrayBlockingQueue<>(100);

    public MediaMetadataProcessor() {
        this.concurrencyLevel = 5;
        this.resolutionStrategy = ResolutionStrategy.FIRST_OCCURRENCE;
        this.logDetails = true;
        this.maxRetries = 3;
        this.supportedFormats = Arrays.asList("mp3", "wav", "avi", "mp4");
    }

    public void startProcessing() {
        ExecutorService executor = Executors.newFixedThreadPool(concurrencyLevel);

        while (true) {
            File file;

            try {
                file = fileQueue.take();

                if (!supportedFormats.contains(getFileExtension(file))) {
                    logger.warn("Unsupported format, skipping...");
                    continue;
                }

                executor.submit(() -> processFile(file));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.error("Processing interrupted", e);
                break;
            }
        }
    }

    private void processFile(File file) {
        // Extract metadata using FFmpeg, handle errors and duplicate entries based on config

        // Synchronize with external service, handling rate limits etc.

        logger.info("Successfully processed: " + file.getName());
    }

    private String getFileExtension(File file) {
        String name = file.getName();
        int lastIndexOf = name.lastIndexOf('.');
        if (lastIndexOf == -1) {
            return ""; // Empty extension
        }

        return name.substring(lastIndexOf + 1);
    }

    private enum ResolutionStrategy {
        FIRST_OCCURRENCE, LAST_OCCURRENCE, THROW_EXCEPTION
    }
}
```

