```c
#include <pthread.h>
#include <stdio.h>

pthread_mutex_t lock;
int sharedResource = 0;  // Shared resource that needs to be protected

void *threadFunction(void *arg) {
    pthread_mutex_lock(&lock);  // Acquire lock before accessing the shared resource
    ++sharedResource;  // Modify the shared resource
    printf("%d\n", sharedResource);
    pthread_mutex_unlock(&lock);  // Release lock after modifying the shared resource
}

int main() {
    if (pthread_mutex_init(&lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        return -1;
    }

    pthread_t threadId[2];
    for(int i = 0; i < 2; ++i) {
        if(pthread_create(&threadId[i], NULL, &threadFunction, NULL) != 0) {
            perror("Failed to create a thread");
            return -1;
        }
    }

    for(int i = 0; i < 2; ++i) {
        if(pthread_join(threadId[i], NULL) != 0) {
            perror("Failed to join the threads");
            return -1;
        }
    }

    pthread_mutex_destroy(&lock);  // Destroy mutex after use

    return 0;
}
```
This example demonstrates how to create multiple threads and protect a shared resource using locks. For the rest of your requirements, I'd recommend breaking them down into more manageable tasks, for instance:

