void insertStringAfterFirstOccurrence(std::forward_list<std::string>& flist, 
                                     const std::string& firstStr, 
                                     const std::string& secondStr) {
    auto it = flist.begin();
    for (; it != flist.end(); ++it) {
        if (*it == firstStr) {
            ++it; // move to the next element
            break;
        }
    }

    // insert second string after first occurrence or at end of list
    flist.insert_after(it, secondStr); 
}
