DNS Resolution:
```cpp
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <string.h>
#include <stdio.h>
#include <errno.h>
#define u_char unsigned char
u_char* dnsResolve(const char *hostname, int *error) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // use IPv4 or IPv6, whichever
    hints.ai_socktype = SOCK_STREAM;

    int status = 0;
    if ((status = getaddrinfo(hostname,"http",&hints,&res)) != 0) {
        *error = h_errno; // set error code
        return NULL; // return null on failure
    }
    u_char* ip = (u_char*)malloc(res->ai_addrlen); // allocate memory for IP address
    memcpy(ip, &((struct sockaddr_in *) res->ai_addr)->sin_addr, res->ai_addrlen);

    freeaddrinfo(res); // free the linked list
    return ip;
}
```
