#include <stdlib.h>
#include <string.h>
#include <jansson.h>  // JSON library
#include <pthread.h>

typedef struct ConfigNode {
    char *config;
    int type;  // Indicates the type of configuration e.g., ENV, API key etc.
    struct ConfigNode* next;
} ConfigNode;

ConfigNode *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_config(char* config, int type) {
    pthread_mutex_lock(&lock);  // Start of critical section

    ConfigNode *newNode = malloc(sizeof(ConfigNode));
    newNode->config = strdup(config);
    newNode->type = type;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);  // End of critical section
}

char* parse_and_store(const char *json, void (*log)(int, const char*, ...), int(*validate)(const char*)) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        log(1, "Failed to parse JSON: %s", error.text);
        return strdup("Invalid JSON format");
    }

    if(!validate(json)) {
        json_decref(root);
        return strdup("JSON doesn't pass validation checks");
    }

    // Assuming you have a function like this that takes root, log and validate as parameters:
    void process_configs(json_t* node, void (*log)(int, const char*, ...), int(*validate)(const char*)) { 
        if (json_is_object(node)) {
            json_t *value;
            const char *key;
            json_object_foreach(node, key, value) {
                add_config(key, /* Type of config here */);
                process_configs(value, log, validate);
            }
        } else if (json_is_array(node)) {
            size_t i;
            for(i = 0; i < json_array_size(node); i++) {
                process_configs(json_array_get(node, i), log, validate);
            }
        } else if (json_is_string(node)) {
            add_config(json_string_value(node), /* Type of config here */);
        } 
    }

    process_configs(root, log, validate);
    json_decref(root);
    return NULL;
}
```
In this code, I've used Jansson library for JSON parsing. You can replace it with any other suitable C library like cJSON. 

