import org.springframework.web.client.RestTemplate;

@SpringBootApplication
@RestController
public class RibbonExampleApplication {
    @Autowired
    private RestTemplate restTemplate;

    @RequestMapping("/startClient")
    @HystrixCommand(fallbackMethod = "failover")
    public String startClient() {
        return this.restTemplate.getForObject("http://anotherService/service", String.class);
    }

    public String failover(){
        return "This is a failover method";
    }

    @Bean
    @LoadBalanced
    RestTemplate restTemplate() {
        return new RestTemplate();
    }

    public static void main(String[] args) {
        SpringApplication.run(RibbonExampleApplication.class, args);
    }
}
```

